#!/usr/bin/env python3
"""Dashboard interativo da Squad de Postagens cuidar.vc — pipeline, agendamentos e KPIs.
Servidor stdlib (zero dependências). Estilo visual oficial: gradiente azul + glassmorfismo.
Uso: python3 dashboard.py  → serve em http://<ip>:8800/?k=<token> (token em dashboard-token.txt)
"""
import json, os, re, threading, time, secrets, hashlib, subprocess, calendar as cal_mod
import urllib.request, urllib.error
from datetime import datetime, timezone, timedelta
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
import html as html_mod

BASE = Path(__file__).resolve().parent
SQUAD = BASE.parent                      # /home/hermes/cuidarvc/squad
CRON_OUT = Path("/home/hermes/.hermes/profiles/cuidar/cron/output")  # absoluto: Path.home() aponta pro home do profile
TOKEN_FILE = BASE / "dashboard-token.txt"
PORT = 8800
API = "https://api.zernio.com"
BRT = timezone(timedelta(hours=-3))
HERMES = "/home/hermes/.local/share/uv/tools/hermes-agent/bin/hermes"
ACOES_LOG = BASE / "acoes.jsonl"

AGENTS = [
    ("9587d40be7e7", "1 · Planejador"),
    ("7bd73f39264b", "2 · Copywriter"),
    ("7ab152d68c07", "3 · Artes"),
    ("9e68702df006", "4 · QC"),
    ("d2fd43a7edcd", "5 · Agendador"),
    ("30b5228c9aea", "6 · Métricas"),
    ("b1c27fe585a1", "7 · Community"),
    ("9b7420a209aa", "CMO · Briefing"),
]

# whitelist fixa de ações: só estes job_ids podem ser disparados pelo dashboard (horários conferidos em cron/jobs.json 11/09)
AGENDA = {
    "9587d40be7e7": "08h · 14h · 20h",
    "7bd73f39264b": "09h",
    "7ab152d68c07": "10h",
    "9e68702df006": "11h",
    "d2fd43a7edcd": "12h",
    "30b5228c9aea": "13h",
    "b1c27fe585a1": "a cada 2h",
    "9b7420a209aa": "10h · 21h",
}

if not TOKEN_FILE.exists():
    TOKEN_FILE.write_text(secrets.token_hex(16).strip() + "\n")
    os.chmod(TOKEN_FILE, 0o600)
TOKEN = TOKEN_FILE.read_text().strip()

_api_cache, _api_lock = {}, threading.Lock()
_state_cache, _state_lock = {"ts": 0, "data": None}, threading.Lock()


def zernio(path, ttl=240):
    """GET na API Zernio com cache em memória (erros ficam 30s em cache)."""
    now = time.time()
    with _api_lock:
        hit = _api_cache.get(path)
        if hit:
            ts, data = hit
            efetivo = 30 if (isinstance(data, dict) and "_erro" in data) else ttl
            if now - ts < efetivo:
                return data
    try:
        hdr = (SQUAD / "zernio.hdr").read_text().strip()
        req = urllib.request.Request(f"{API}{path}", headers={"Authorization": hdr.replace("Authorization:", "").strip()})
        with urllib.request.urlopen(req, timeout=20) as r:
            data = json.loads(r.read().decode())
    except Exception as e:
        with _api_lock:
            _api_cache[path] = (now, {"_erro": str(e)})
        return {"_erro": str(e)}
    with _api_lock:
        _api_cache[path] = (now, data)
    return data


def read_text(p, limit=4000):
    try:
        t = Path(p).read_text(errors="replace")
        return t[:limit]
    except Exception:
        return ""


def latest_file(d):
    try:
        files = sorted(Path(d).glob("*.md"), key=lambda f: f.stat().st_mtime, reverse=True)
        return files[0] if files else None
    except Exception:
        return None


def agent_state(job_id, nome):
    d = CRON_OUT / job_id
    f = latest_file(d)
    st = {"nome": nome, "run": None, "resumo": "", "status": "sem runs"}
    if not f:
        return st
    try:
        txt = f.read_text(errors="replace")
    except Exception:
        return st
    m = re.search(r"\*\*Run Time:\*\* ([0-9\- :]+)", txt)
    resp = txt.rsplit("## Response", 1)[-1].strip() if "## Response" in txt else txt[-900:]
    resp = re.sub(r"\n{3,}", "\n\n", resp).strip()
    run = m.group(1) if m else f.stem.replace("_", " ")
    st.update(run=run, resumo=resp[:1600], status="ok")
    try:
        ts = f.stat().st_mtime
        age_h = (time.time() - ts) / 3600
        if age_h > 26:
            st["status"] = "atrasado"
    except Exception:
        pass
    return st


def entregaveis():
    hoje = datetime.now(BRT).strftime("%Y-%m-%d")
    pauta_f = latest_file(SQUAD / "pautas")
    copy_f = latest_file(SQUAD / "copys")
    qc_f = latest_file(SQUAD / "qc")
    cal_f = latest_file(SQUAD / "calendario")

    pauta = read_text(pauta_f, 2200) if pauta_f else ""
    copy = read_text(copy_f, 2200) if copy_f else ""
    qc_txt = read_text(qc_f, 4000) if qc_f else ""
    veredito = "sem QC hoje"
    if re.search(r"APROVAD[OA]", qc_txt, re.I):
        veredito = "aprovado"
    elif re.search(r"REPROVAD[OA]|\bAJUSTE\b|\bCORRIGIR\b", qc_txt, re.I):
        veredito = "reprovado/ajustes"
    cal = read_text(cal_f, 1800) if cal_f else ""

    # artes recentes (recursive, top 12 por mtime)
    artes = []
    try:
        pngs = [p for p in (SQUAD / "artes").rglob("*.png") if p.is_file()]
        pngs += [p for p in (SQUAD / "artes").rglob("*.jpg") if p.is_file()]
        pngs.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        artes = [{"p": str(p.relative_to(SQUAD)), "t": datetime.fromtimestamp(p.stat().st_mtime, BRT).strftime("%d/%m %Hh")} for p in pngs[:12]]
    except Exception:
        pass

    return {"hoje": hoje, "pauta_arq": pauta_f.name if pauta_f else None, "pauta": pauta,
            "copy_arq": copy_f.name if copy_f else None, "copy": copy,
            "qc_arq": qc_f.name if qc_f else None, "qc_veredito": veredito,
            "cal_arq": cal_f.name if cal_f else None, "calendario": cal,
            "artes": artes}


def brt(iso):
    if not iso:
        return ""
    try:
        dt = datetime.fromisoformat(iso.replace("Z", "+00:00"))
        return dt.astimezone(BRT).strftime("%d/%m %H:%M")
    except Exception:
        return iso


def posts_state():
    d = zernio("/v1/posts?limit=50")
    out = []
    for p in d.get("posts", []):
        out.append({
            "id": p.get("_id"),
            "status": p.get("status"),
            "quando": brt(p.get("scheduledFor")),
            "redes": [pl.get("platform") for pl in p.get("platforms", [])],
            "titulo": p.get("title") or "",
            "content": (p.get("content") or "")[:1400],
            "n_media": len(p.get("mediaItems", [])),
            "criado": brt(p.get("createdAt")),
            "iso": p.get("scheduledFor") or "",
        })
    return {"posts": out, "erro": d.get("_erro")}


def kpis_state():
    contas = zernio("/v1/accounts")
    ig_id = next((a.get("_id") for a in contas.get("accounts", []) if a.get("platform") == "instagram"), "")
    stats = zernio("/v1/accounts/follower-stats")
    hist = zernio(f"/v1/analytics/instagram/follower-history?accountId={ig_id}") if ig_id else {}
    ov = zernio("/v1/analytics")
    best = zernio(f"/v1/analytics/best-time?platform=instagram&accountId={ig_id}") if ig_id else {}

    contas_l = []
    for a in contas.get("accounts", []):
        contas_l.append({"id": a.get("_id"), "plataforma": a.get("platform"),
                         "user": a.get("username") or a.get("displayName")})
    overview = ov.get("overview", {}) if isinstance(ov, dict) else {}
    # follower history: série pra gráfico se existir
    serie = []
    try:
        fh = hist.get("follower_count") or {}
        data = fh.get("data") or hist.get("data") or []
        for pt in data:
            serie.append({"d": pt.get("date") or pt.get("day") or "", "v": int(pt.get("value") or pt.get("count") or 0)})
    except Exception:
        pass
    hist_total = {}
    try:
        m = (hist.get("metrics") or {}).get("follower_count", {})
        hist_total = {"followers": m.get("total"), "gained": (hist.get("metrics") or {}).get("followers_gained", {}).get("total"),
                      "lost": (hist.get("metrics") or {}).get("followers_lost", {}).get("total")}
    except Exception:
        pass
    return {"contas": contas_l, "follower_stats": stats, "hist_total": hist_total, "serie": serie,
            "overview": {"totalPosts": overview.get("totalPosts"), "publishedPosts": overview.get("publishedPosts"),
                         "scheduledPosts": overview.get("scheduledPosts"), "lastSync": overview.get("lastSync")},
            "best_time": best.get("slots", [])}


def _rodando_agora(job_id):
    """Agente em execução: processo com o job_id na linha de comando OU arquivo de saída fresco (<10 min)."""
    try:
        out = subprocess.run(["pgrep", "-af", job_id], capture_output=True, text=True, timeout=5).stdout.strip()
        if out and "dashboard" not in out:
            return True
    except Exception:
        pass
    try:
        f = latest_file(CRON_OUT / job_id)
        if f and time.time() - f.stat().st_mtime < 600:
            return True
    except Exception:
        pass
    return False


def _primeira_linha_util(txt):
    for ln in txt.splitlines():
        ln = ln.strip().lstrip("*-#• ").strip()
        if len(ln) > 10 and not ln.startswith("```") and not ln.lower().startswith("run time"):
            ln = re.sub(r"\*+", "", ln)
            return (ln[:97] + "…") if len(ln) > 100 else ln
    return ""


def equipe_state(agora, pipeline):
    out = []
    for job_id, nome in AGENTS:
        ag = next((a for a in pipeline if a.get("nome") == nome), {})
        f = latest_file(CRON_OUT / job_id)
        ocupado = _rodando_agora(job_id)
        o_que, arq, ts = "", None, None
        if f:
            try:
                arq, ts = f.name, f.stat().st_mtime
                txt = f.read_text(errors="replace")
                resp = txt.rsplit("## Response", 1)[-1] if "## Response" in txt else txt
                o_que = _primeira_linha_util(resp)
            except Exception:
                pass
        status = "trabalhando" if ocupado else (ag.get("status") or "sem runs")
        out.append({"nome": nome, "job": job_id, "agenda": AGENDA.get(job_id, "—"),
                    "status": status, "o_que": o_que, "arquivo": arq,
                    "quando": _ha(ts, agora) if ts else ""})
    return out


_MESES = ["janeiro", "fevereiro", "março", "abril", "maio", "junho",
          "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"]


def calendario_state(ano, mes, posts_res):
    """Grade do mês com os posts do Zernio + as ideias pautadas (ainda não produzidas)."""
    hoje_str = datetime.now(BRT).strftime("%Y-%m-%d")
    dias = {}
    for p in posts_res.get("posts", []):
        dstr = _iso_brt_date(p.get("iso"))
        if not dstr:
            continue
        dias.setdefault(dstr, []).append({
            "tipo": p.get("status"), "hora": _iso_brt_hm(p.get("iso")),
            "titulo": p.get("titulo") or _tit_from_content(p.get("content")),
            "redes": p.get("redes") or [], "id": p.get("id")})
    pautas_dir = SQUAD / "pautas"
    vistos = set()
    if pautas_dir.is_dir():
        for pf in sorted(pautas_dir.glob("pauta-*.md"), reverse=True):
            try:
                txt = pf.read_text(errors="replace")
            except Exception:
                continue
            for linha in re.findall(r"^### \d+\. .+$", txt, re.M):
                m = re.search(r'"([^"]{4,90})"', linha)
                d = re.search(r"(\d{1,2})/(\d{1,2})", linha)
                if not d:
                    continue
                dia_p, mes_p = int(d.group(1)), int(d.group(2))
                if mes_p != mes or not (1 <= dia_p <= 31):
                    continue
                dstr = f"{ano}-{mes:02d}-{dia_p:02d}"
                titulo = m.group(1) if m else linha[4:64].strip()
                if (dstr, titulo) in vistos:
                    continue
                vistos.add((dstr, titulo))
                dias.setdefault(dstr, []).append({
                    "tipo": "planejado", "hora": "",
                    "titulo": titulo, "redes": [], "id": None})
    semanas = []
    for semana in cal_mod.Calendar(firstweekday=6).monthdayscalendar(ano, mes):
        linha = []
        for dia in semana:
            if dia == 0:
                linha.append(None)
                continue
            dstr = f"{ano}-{mes:02d}-{dia:02d}"
            itens = dias.get(dstr, [])
            linha.append({"dia": dia, "data": dstr, "hoje": dstr == hoje_str,
                          "total": len(itens),
                          "chips": [{"tipo": i["tipo"], "hora": i["hora"],
                                     "titulo": i["titulo"][:46], "redes": i["redes"]} for i in itens[:3]]})
        semanas.append(linha)
    return {"ano": ano, "mes": mes, "titulo": f"{_MESES[mes-1]} de {ano}",
            "semanas": semanas, "detalhes": dias}


def _tit_from_content(c):
    if not c:
        return "(sem título)"
    primeira = c.strip().splitlines()[0].strip()
    if len(primeira) > 70:
        primeira = primeira[:70].rsplit(" ", 1)[0] + "…"
    return primeira


def _ha(ts, agora):
    try:
        h = (agora.timestamp() - ts) / 3600
    except Exception:
        return ""
    if h < 1:
        return f"há {max(int(h * 60), 1)} min"
    if h < 48:
        return f"há {int(h)}h"
    return f"há {int(h / 24)} dias"


def _iso_brt_date(iso):
    try:
        return datetime.fromisoformat((iso or "").replace("Z", "+00:00")).astimezone(BRT).strftime("%Y-%m-%d")
    except Exception:
        return ""


def _iso_brt_hm(iso):
    try:
        return datetime.fromisoformat((iso or "").replace("Z", "+00:00")).astimezone(BRT).strftime("%H:%M")
    except Exception:
        return ""


def esteira_state(agora, posts_res, pipeline):
    posts = posts_res.get("posts", [])
    pub = [p for p in posts if p.get("status") == "published"]
    sch = [p for p in posts if p.get("status") == "scheduled"]
    fal = [p for p in posts if p.get("status") in ("failed", "partial")]
    hoje = agora.strftime("%Y-%m-%d")
    amanha = (agora + timedelta(days=1)).strftime("%Y-%m-%d")

    # pauta: ideias da pauta mais recente
    pauta_f = latest_file(SQUAD / "pautas")
    ideias, pauta_ts = [], None
    if pauta_f:
        try:
            pauta_ts = pauta_f.stat().st_mtime
            txt = pauta_f.read_text(errors="replace")
            for linha in re.findall(r"^### \d+\. .+$", txt, re.M):
                m = re.search(r'"([^"]{4,90})"', linha)
                titulo = m.group(1) if m else linha[:70]
                d = re.search(r"(Sáb|Dom|Seg|Ter|Qua|Qui|Sex) (\d{2}/\d{2})", linha)
                data = f"{d.group(1)} {d.group(2)}" if d else "sem data"
                p = re.search(r"\((P[\d/]+)\)", linha)
                ideias.append({"t": titulo, "data": data, "pilar": p.group(1) if p else ""})
        except Exception:
            pass

    # copy do dia
    copy_f = latest_file(SQUAD / "copys")
    copy_peca = None
    if copy_f:
        try:
            ctxt = copy_f.read_text(errors="replace")
            m = re.search(r"Assunto escolhido[^\n]*\n[^\n]*?\"([^\"]{4,90})\"", ctxt)
            if not m:
                m = re.search(r'"([^"]{10,90})"', ctxt.split("## FORMATO")[0])
            if m:
                copy_peca = {"t": m.group(1), "ts": copy_f.stat().st_mtime}
        except Exception:
            pass

    # arte do dia (última pasta artes-AAAA-MM-DD)
    arte_dir, arte_n, arte_ts = None, 0, None
    try:
        pastas = sorted([d for d in (SQUAD / "artes").iterdir()
                         if d.is_dir() and re.match(r"artes-\d{4}", d.name)], key=lambda d: d.name)
        if pastas:
            arte_dir = pastas[-1]
            cards = sorted(arte_dir.glob("card-*.png"))
            arte_n = len(cards)
            arte_ts = cards[0].stat().st_mtime if cards else arte_dir.stat().st_mtime
    except Exception:
        pass

    # QC mais recente
    qc_f = latest_file(SQUAD / "qc")
    qc_ver, qc_subj, qc_ts = "sem QC", "", None
    if qc_f:
        try:
            qc_ts = qc_f.stat().st_mtime
            qtxt = qc_f.read_text(errors="replace")[:3000]
            m = re.search(r"Veredito:\s*(?:✅\s*)?(APROVAD[OA]|REPROVAD[OA]|AJUSTES?)", qtxt, re.I)
            if m:
                qc_ver = m.group(1).lower()
            m2 = re.search(r'Veredito:[^\n]*?"([^"]{4,90})"', qtxt)
            if m2:
                qc_subj = m2.group(1)
        except Exception:
            pass

    # precisa de você
    precisa = []
    for linha in read_text(SQUAD / "community" / "escalacoes.md", 8000).splitlines():
        m = re.match(r"^-\s*\[ \]\s*(.+)$", linha.strip())
        if not m:
            continue
        partes = [x.strip() for x in m.group(1).split("|")]
        tag = partes[1] if len(partes) > 1 else "Community"
        quem = partes[3] if len(partes) > 3 else ""
        resumo = partes[4] if len(partes) > 4 else m.group(1)
        precisa.append({"tag": tag, "txt": f"{quem}: {resumo}" if quem else resumo})
    if qc_ver.startswith("reprov") or qc_ver.startswith("ajuste"):
        precisa.append({"tag": "Qualidade", "txt": f"Peça devolvida pelo QC: {qc_subj or 'ver arquivo'}. Aguardando redo."})
    atrasados = [a["nome"] for a in pipeline if a.get("status") == "atrasado"]
    for nome in atrasados:
        precisa.append({"tag": "Watchdog", "txt": f"{nome} sem run há mais de 26h."})
    atraso_posts, atraso_ids = [], set()
    for p in sch:
        try:
            dt = datetime.fromisoformat(p.get("iso").replace("Z", "+00:00")).astimezone(BRT)
            if (agora - dt).total_seconds() > 3600:
                atraso_posts.append(p)
                atraso_ids.add(p.get("id"))
                precisa.append({"tag": "Agendador", "txt": f"Passou do horário e segue agendado: {_tit_from_content(p.get('content'))} ({p.get('quando')}). Confirme no Zernio."})
        except Exception:
            pass
    for p in fal:
        precisa.append({"tag": "Publicação", "txt": f"Post com falha/parcial: {_tit_from_content(p.get('content'))}. Ver Zernio."})
    if not any(_iso_brt_date(p.get("iso")) == amanha for p in sch):
        precisa.append({"tag": "Watchdog", "txt": "Nenhuma peça agendada para amanhã ainda. Mínimo: 1 post/dia."})

    # publicado (3 mais recentes) com métricas reais por post
    publ = []
    for p in sorted(pub, key=lambda x: x.get("iso") or "", reverse=True)[:3]:
        mm = {"alcance": 0, "curtidas": 0, "comentarios": 0, "impressoes": 0}
        if p.get("id"):
            tl = zernio(f"/v1/analytics/post-timeline?postId={p['id']}")
            try:
                for pt in tl.get("timeline", []):
                    mm["alcance"] += int(pt.get("reach") or 0)
                    mm["curtidas"] += int(pt.get("likes") or 0)
                    mm["comentarios"] += int(pt.get("comments") or 0)
                    mm["impressoes"] += int(pt.get("impressions") or 0)
            except Exception:
                pass
        publ.append({"t": _tit_from_content(p.get("content")), "quando": p.get("quando"), "m": mm})

    # contas + community
    contas_l = []
    try:
        for a in zernio("/v1/accounts").get("accounts", []):
            ult = max((_iso_brt_hm(x.get("iso")) for x in pub if a.get("platform") in (x.get("redes") or [])), default="")
            contas_l.append({"nome": a.get("displayName") or a.get("username") or a.get("platform"),
                             "plataforma": a.get("platform"), "user": a.get("username"),
                             "ativa": bool(a.get("isActive")), "ultimo": ult})
    except Exception:
        pass
    community = {"comentarios": 0, "conversas": 0, "atualizado": ""}
    try:
        com = json.loads((SQUAD / "community" / "estado.json").read_text())
        community = {"comentarios": len(com.get("comentarios_processados", [])),
                     "conversas": len(com.get("conversas", {})),
                     "atualizado": brt(com.get("atualizado_em"))}
    except Exception:
        pass

    n_pub_hoje = len([p for p in pub if _iso_brt_date(p.get("iso")) == hoje])
    stages = [
        {"nome": "1 · Pauta", "sub": f"{len(ideias)} ideia(s) pautadas",
         "cards": [{"t": i["t"], "tag": i["pilar"] or "pauta", "quando": i["data"] + (" · " + _ha(pauta_ts, agora) if pauta_ts else "")} for i in ideias[:5]]},
        {"nome": "2 · Copy", "sub": "post do dia" if copy_peca else "aguardando",
         "cards": [{"t": copy_peca["t"], "tag": "copy", "quando": _ha(copy_peca["ts"], agora)}] if copy_peca else []},
        {"nome": "3 · Arte", "sub": f"{arte_n} card(s) entregues" if arte_dir else "aguardando",
         "cards": [{"t": f"Carrossel do dia ({arte_n} cards)", "tag": "arte", "quando": _ha(arte_ts, agora),
                    "thumb": str((arte_dir / "card-1.png").relative_to(SQUAD)) if (arte_dir / "card-1.png").is_file() else None}] if arte_dir else []},
        {"nome": "4 · Qualidade", "sub": qc_ver,
         "cards": [{"t": qc_subj or "veredito registrado", "tag": "QC", "quando": _ha(qc_ts, agora),
                    "alerta": bool(qc_ver and not qc_ver.startswith("aprov"))}] if qc_f else []},
        {"nome": "5 · Agendada", "sub": f"{len(sch)} no Zernio",
         "cards": [{"t": _tit_from_content(p.get("content")), "tag": ", ".join(p.get("redes") or []) or "zernio",
                    "quando": f"vai ao ar {p.get('quando')}", "alerta": p.get("id") in atraso_ids} for p in sch[:4]]},
        {"nome": "6 · Publicada", "sub": f"{len(pub)} no total",
         "cards": [{"t": b["t"], "tag": "no ar", "quando": b["quando"], "metricas": b["m"]} for b in publ]},
    ]
    em_prod = len(ideias) + (1 if copy_peca else 0) + (1 if arte_dir else 0) + (1 if qc_f else 0) + len(sch)
    return {
        "resumo": {"pub_hoje": n_pub_hoje, "em_prod": em_prod,
                   "voce": len(precisa), "parada": len(atraso_posts) + len(atrasados) + len(fal)},
        "precisa": precisa,
        "stages": stages,
        "publicado": publ,
        "contas": contas_l,
        "community": community,
    }


def build_state():
    agora = datetime.now(BRT)
    pipeline = [agent_state(j, n) for j, n in AGENTS]
    posts = posts_state()
    s = {
        "gerado_em": agora.strftime("%d/%m/%Y %H:%M (Brasília)"),
        "pipeline": pipeline,
        "entreg": entregaveis(),
        "posts": posts,
        "kpis": kpis_state(),
        "esteira": esteira_state(agora, posts, pipeline),
        "equipe": equipe_state(agora, pipeline),
    }
    return s


_build_lock = threading.Lock()

def get_state():
    with _state_lock:
        if _state_cache["data"] and time.time() - _state_cache["ts"] < 60:
            return _state_cache["data"]
    with _build_lock:
        with _state_lock:
            if _state_cache["data"] and time.time() - _state_cache["ts"] < 60:
                return _state_cache["data"]
        data = build_state()
        with _state_lock:
            _state_cache.update(ts=time.time(), data=data)
        return data


