<script>
const K=new URLSearchParams(location.search).get('k');
// esc() escapa TODO conteúdo interpolado em innerHTML (mitigação XSS); nenhuma string não-escapada entra no DOM
const esc=s=>(s===0?'0':(s||'')).toString().replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function tab(id,el){document.querySelectorAll('.tab').forEach(t=>t.classList.remove('on'));el.classList.add('on');
 document.querySelectorAll('.painel').forEach(p=>p.classList.remove('on'));document.getElementById(id).classList.add('on');
 if(id==='calend'&&!calAno){const n=new Date();carregaCal(n.getFullYear(),n.getMonth()+1);}}
async function carrega(){
 if(!K){document.getElementById('semtoken').style.display='block';return;}
 try{
 const r=await fetch('api/state?k='+encodeURIComponent(K));if(!r.ok){document.getElementById('meta').textContent='erro '+r.status;return;}
 const s=await r.json();
 document.getElementById('meta').textContent='atualizado em '+s.gerado_em+' · auto-refresh 5 min';
 renderEsteira(s);
 renderEquipe(s);
 // pipeline
 const lp=document.getElementById('lp');lp.innerHTML='';
 s.pipeline.forEach(a=>{const d=document.createElement('div');d.className='pcard';
  const cls=a.status==='ok'?'b-ok':(a.status==='atrasado'?'b-atrasado':'b-sem');
  d.innerHTML='<div class="nome">'+esc(a.nome)+'</div><div class="run">último run: '+esc(a.run||'—')+'</div>'
   +'<span class="badge '+cls+'">'+esc(a.status)+'</span>'
   +(a.resumo?'<details><summary>ver saída</summary><div class="resumo">'+esc(a.resumo)+'</div></details>':'');
  lp.appendChild(d);});
 const e=s.entreg;
 document.getElementById('pauta').textContent=e.pauta||'(sem pauta ainda)';
 document.getElementById('pauta_arq').textContent=e.pauta_arq||'';
 document.getElementById('copy').textContent=e.copy||'(sem copy ainda)';
 document.getElementById('copy_arq').textContent=e.copy_arq||'';
 const qc=document.getElementById('qc');
 qc.textContent=e.qc_veredito;
 qc.style.color=e.qc_veredito==='aprovado'?'#6ee7b7':(e.qc_veredito==='sem QC hoje'?'#cbd5e1':'#fca5a5');
 document.getElementById('qctxt').textContent=e.qc_veredito==='aprovado'?'Veredito do QC mais recente registrado nos arquivos da squad.':'';
 document.getElementById('cal').textContent=e.calendario||'(sem calendário)';
 const gal=document.getElementById('artes');gal.innerHTML='';
 (e.artes||[]).forEach(a=>{const img=document.createElement('img');
  img.src='media?k='+encodeURIComponent(K)+'&p='+encodeURIComponent(a.p);img.title=a.t;
  img.onclick=()=>window.open(img.src,'_blank');gal.appendChild(img);});
 // agendamentos
 const P=s.posts.posts||[];
 const n=P.filter(p=>p.status==='scheduled').length,np=P.filter(p=>p.status==='published').length,nf=P.filter(p=>p.status==='failed'||p.status==='partial').length;
 document.getElementById('agd_kpi').innerHTML=
  card(np,'publicados')+card(n,'agendados')+card(nf,'falha/parcial')+card(P.length,'no Zernio (últimos 50)');
 document.getElementById('tp').innerHTML=P.map(p=>'<tr><td><span class="pill p-'+esc(p.status)+'">'+esc(p.status)+'</span></td>'
