886	class H(BaseHTTPRequestHandler):
887	    def log_message(self, fmt, *a):
888	        try:
889	            line = fmt % a
890	            line = re.sub(r"[?&]k=[^&\s]+", "k=***", line)
891	            print(f"[{datetime.now(BRT):%d/%m %H:%M:%S}] {line}", flush=True)
892	        except Exception:
893	            pass
894	
895	    def _send(self, code, body, ctype="application/json; charset=utf-8"):
896	        self.send_response(code)
897	        self.send_header("Content-Type", ctype)
898	        self.send_header("Cache-Control", "no-store")
899	        self.send_header("X-Content-Type-Options", "nosniff")
900	        self.send_header("Referrer-Policy", "no-referrer")
901	        self.send_header("X-Frame-Options", "DENY")
902	        self.send_header("Content-Length", str(len(body)))
903	        self.end_headers()
904	        try:
905	            self.wfile.write(body)
906	        except (BrokenPipeError, ConnectionResetError):
907	            pass
908	
909	    def _ok(self, q):
910	        k = q.get("k", [""])[0]
911	        if not k:
912	            return False
913	        return secrets.compare_digest(k, TOKEN)
914	
915	    def do_POST(self):
916	        from urllib.parse import urlparse, parse_qs
917	        u = urlparse(self.path)
918	        q = parse_qs(u.query)
919	        if u.path != "/api/acao":
920	            return self._send(404, b'{"erro":"rota"}')
921	        if not self._ok(q):
922	            return self._send(403, b'{"erro":"token"}')
923	        try:
924	            n = int(self.headers.get("Content-Length") or 0)
925	            body = json.loads(self.rfile.read(n).decode()) if n else {}
926	        except Exception:
927	            return self._send(400, b'{"erro":"json"}')
928	        agente = str(body.get("agente") or "")
929	        # whitelist: só job_ids da própria squad, nada vem do cliente além da escolha
930	        nome_ag = next((n for j, n in AGENTS if j == agente), None)
931	        if not nome_ag or agente not in AGENDA:
932	            return self._send(400, json.dumps({"ok": False, "msg": "agente fora da lista permitida"}, ensure_ascii=False).encode())
933	        if _rodando_agora(agente):
934	            return self._send(200, json.dumps({"ok": True, "msg": f"{nome_ag} já está trabalhando agora; disparo ignorado."}, ensure_ascii=False).encode())
935	        try:
936	            logs = BASE / "logs"
937	            logs.mkdir(exist_ok=True)
938	            logf = logs / f"acao-{agente[:8]}-{datetime.now(BRT).strftime('%Y%m%d-%H%M%S')}.log"
939	            with open(logf, "wb") as fh:
940	                subprocess.Popen([HERMES, "-p", "cuidar", "cron", "run", agente],
941	                                 stdout=fh, stderr=subprocess.STDOUT, start_new_session=True)
942	            os.chmod(logf, 0o600)
943	            with open(ACOES_LOG, "a") as fh:
944	                fh.write(json.dumps({"ts": datetime.now(BRT).isoformat(), "agente": agente,
945	                                     "acao": "rodar", "origem": "dashboard"}, ensure_ascii=False) + "\n")
946	            os.chmod(ACOES_LOG, 0o600)
947	            msg = f"{nome_ag} disparado. O resultado aparece na esteira em alguns minutos."
948	        except Exception as e:
949	            return self._send(500, json.dumps({"ok": False, "msg": f"falha ao disparar: {e}"}, ensure_ascii=False).encode())
950	        return self._send(200, json.dumps({"ok": True, "msg": msg}, ensure_ascii=False).encode())
