 return '<svg viewBox="0 0 '+w+' '+h+'" style="width:100%"><polyline points="'+pts+'" fill="none" stroke="#67e8f9" stroke-width="3"/>'+serie.map((p,i)=>'<circle cx="'+x(i)+'" cy="'+y(p.v)+'" r="4" fill="#fff"><title>'+esc(p.d)+': '+esc(p.v)+'</title></circle>').join('')+lbl+'</svg>';}
carrega();setInterval(carrega,300000);
</script></body></html>"""


class H(BaseHTTPRequestHandler):
    def log_message(self, fmt, *a):
        try:
            line = fmt % a
            line = re.sub(r"[?&]k=[^&\s]+", "k=***", line)
            print(f"[{datetime.now(BRT):%d/%m %H:%M:%S}] {line}", flush=True)
        except Exception:
            pass

    def _send(self, code, body, ctype="application/json; charset=utf-8"):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def _ok(self, q):
        k = q.get("k", [""])[0]
        if not k:
            return False
        return secrets.compare_digest(k, TOKEN)

    def do_POST(self):
        from urllib.parse import urlparse, parse_qs
        u = urlparse(self.path)
        q = parse_qs(u.query)
        if u.path != "/api/acao":
            return self._send(404, b'{"erro":"rota"}')
        if not self._ok(q):
            return self._send(403, b'{"erro":"token"}')
        try:
            n = int(self.headers.get("Content-Length") or 0)
            body = json.loads(self.rfile.read(n).decode()) if n else {}
        except Exception:
            return self._send(400, b'{"erro":"json"}')
        agente = str(body.get("agente") or "")
        # whitelist: só job_ids da própria squad, nada vem do cliente além da escolha
        nome_ag = next((n for j, n in AGENTS if j == agente), None)
        if not nome_ag or agente not in AGENDA:
            return self._send(400, json.dumps({"ok": False, "msg": "agente fora da lista permitida"}, ensure_ascii=False).encode())
        if _rodando_agora(agente):
            return self._send(200, json.dumps({"ok": True, "msg": f"{nome_ag} já está trabalhando agora; disparo ignorado."}, ensure_ascii=False).encode())
        try:
            logs = BASE / "logs"
            logs.mkdir(exist_ok=True)
            logf = logs / f"acao-{agente[:8]}-{datetime.now(BRT).strftime('%Y%m%d-%H%M%S')}.log"
            with open(logf, "wb") as fh:
                subprocess.Popen([HERMES, "-p", "cuidar", "cron", "run", agente],
                                 stdout=fh, stderr=subprocess.STDOUT, start_new_session=True)
            os.chmod(logf, 0o600)
            with open(ACOES_LOG, "a") as fh:
                fh.write(json.dumps({"ts": datetime.now(BRT).isoformat(), "agente": agente,
                                     "acao": "rodar", "origem": "dashboard"}, ensure_ascii=False) + "\n")
            os.chmod(ACOES_LOG, 0o600)
            msg = f"{nome_ag} disparado. O resultado aparece na esteira em alguns minutos."
        except Exception as e:
            return self._send(500, json.dumps({"ok": False, "msg": f"falha ao disparar: {e}"}, ensure_ascii=False).encode())
        return self._send(200, json.dumps({"ok": True, "msg": msg}, ensure_ascii=False).encode())

    def do_GET(self):
        from urllib.parse import urlparse, parse_qs
        u = urlparse(self.path)
        q = parse_qs(u.query)
        if u.path == "/api/health":
            return self._send(200, b'{"ok":true}')
        if not self._ok(q):
            return self._send(403, b'{"erro":"token"}')
        if u.path == "/":
            return self._send(200, PAGE.encode(), "text/html; charset=utf-8")
        if u.path == "/api/state":
            return self._send(200, json.dumps(get_state(), ensure_ascii=False).encode())
        if u.path == "/api/calendario":
            try:
                ano = int(q.get("ano", ["0"])[0]) or datetime.now(BRT).year
                mes = int(q.get("mes", ["0"])[0]) or datetime.now(BRT).month
            except Exception:
                ano, mes = datetime.now(BRT).year, datetime.now(BRT).month
            if not (1 <= mes <= 12) or not (2024 <= ano <= 2100):
                return self._send(400, b'{"erro":"data"}')
            return self._send(200, json.dumps(calendario_state(ano, mes, posts_state()), ensure_ascii=False).encode())
        if u.path == "/media":
            rel = q.get("p", [""])[0]
            base = (SQUAD).resolve()
            alvo = (base / rel).resolve()
            if not alvo.is_relative_to(base) or alvo.suffix.lower() not in (".png", ".jpg", ".jpeg") or not alvo.is_file():
                return self._send(404, b'{"erro":"nao encontrado"}')
            return self._send(200, alvo.read_bytes(), "image/png" if alvo.suffix.lower() == ".png" else "image/jpeg")
        return self._send(404, b'{"erro":"rota"}')


if __name__ == "__main__":
    srv = ThreadingHTTPServer(("127.0.0.1", PORT), H)
    print(f"dashboard cuidar.vc na porta {PORT}, token em {TOKEN_FILE}")
    srv.serve_forever()

