const K=new URLSearchParams(location.search).get('k')||'';
const MESES=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const MESES_MIN=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const $=id=>document.getElementById(id);
// esc() escapa TODO conteúdo interpolado em innerHTML; null e undefined viram texto vazio
const esc=s=>(s===0?'0':(s===null||s===undefined?'':String(s))).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>(v===null||v===undefined||v===''||!isFinite(Number(v)))?'sem dado':Number(v).toLocaleString('pt-BR');
const midia=m=>'media/'+encodeURIComponent(m)+'?k='+encodeURIComponent(K);
const plural=(n,um,varios)=>n===1?um:varios;
