function trocaAba(a){
 document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('on',t.dataset.aba===a));
 document.querySelectorAll('.painel').forEach(p=>p.classList.toggle('on',p.id==='p-'+a));
 history.replaceState(null,'',location.pathname+location.search+'#'+a);
}

async function carrega(){
 if(!K){$('semtoken').style.display='block';return;}
 try{
  const r=await fetch('api/state?k='+encodeURIComponent(K));
  if(!r.ok){$('meta').textContent='não foi possível atualizar (código '+r.status+')';return;}
  S=await r.json();P=S.pecas||{};
  $('meta').textContent='atualizado '+S.gerado_em+' (Brasília)'+(S.zernio_ok?'':', Zernio sem resposta agora');
  renderHoje();
  if(!calA){const [y,m]=S.hoje.split('-').map(Number);calA=y;calM=m;}
  renderCal();renderRes();
  $('rodape').textContent='Todos os horários em Brasília. Fontes: arquivos da squad e Zernio.';
 }catch(e){$('meta').textContent='falha ao atualizar, tentando de novo em instantes';}
}

function renderHoje(){
 $('frase').textContent=S.frase;
 const pr=S.precisa||[];
 $('precisa').innerHTML=pr.length?pr.map(x=>{
  const clic=x.peca?' data-p="'+esc(x.peca)+'" tabindex="0" role="button"':'';
  const extra=(x.link?' <a class="lnk" href="'+esc(x.link)+'" target="_blank" rel="noopener noreferrer">abrir no Instagram</a>':'')
   +(x.alvo?' <button class="btn ok" data-decidir="resolvido" data-alvo="'+esc(x.alvo)+'">já resolvi</button>':'');
  return '<div class="item"'+clic+'><span class="tag">'+esc(x.tag)+'</span><div class="txt">'+esc(x.texto)
   +(x.meta?'<small>'+esc(x.meta)+'</small>':'')+(extra?'<div style="margin-top:6px">'+extra+'</div>':'')+'</div></div>';
 }).join(''):'<div class="vazio">Nada precisa de você agora</div>';
 const px=S.prox24||[];
 $('prox24').innerHTML=px.length?px.map(x=>'<div class="item" data-p="'+esc(x.peca)+'" tabindex="0" role="button"><span class="hora'+(x.quando.indexOf('a definir')>=0?' def':'')+'">'+esc(x.quando)+'</span><div class="txt"><b>'+esc(x.titulo)+'</b><small>'+esc(x.rede)+', '+esc(x.estado)+'</small></div></div>').join('')
  :'<div class="vazio">Nada programado para as próximas 24h</div>';
 $('esteira').innerHTML=(S.esteira||[]).map(c=>{
  const cards=c.ids.map(id=>{const p=P[id];if(!p)return '';
   const th=(p.imgs&&p.imgs.length)?'<div class="th"><img loading="lazy" alt="" src="'+midia(p.imgs[0])+'" onload="this.style.opacity=1"></div>':'';
   const d=p.hora&&p.etapa!=='publicada'?p.dia+' às '+p.hora:p.dia;
   return '<div class="pc'+(p.alerta?' alerta':'')+'" data-p="'+esc(id)+'" tabindex="0" role="button">'+th+'<div class="d">'+esc(d)+'</div><div class="t">'+esc(p.titulo)+'</div><div class="e">'+esc(p.estado)+'</div></div>';
  }).join('');
  return '<div class="col"><h3><span>'+esc(c.rotulo)+'</span><b>'+(c.ids.length+c.mais)+'</b></h3>'+(cards||'<div class="nada">nenhuma peça aqui</div>')
   +(c.mais?'<div class="mais">mais '+c.mais+' no calendário</div>':'')+'</div>';
 }).join('');
 $('faixa').innerHTML=(S.agentes||[]).map(a=>'<div class="ag"><span class="dot '+esc(a.cor)+'"></span><div><b>'+esc(a.nome)+'</b><div class="s">'+esc(a.status)+'</div>'
  +(a.proxima?'<div class="s">próxima '+esc(a.proxima)+'</div>':'')+'</div><button class="btn" data-rodar="'+a.i+'"'+(a.pode_rodar?'':' disabled')+'>rodar agora</button></div>').join('');
}

function tipoChip(p){return p.etapa==='publicada'?'c-pub':(p.etapa==='agendada'&&p.hora?'c-ag':'c-pa');}
function renderCal(){
 $('cal-titulo').textContent=MESES[calM-1]+' de '+calA;
