#dr{position:fixed;top:0;right:0;height:100%;width:min(480px,100%);z-index:21;transform:translateX(105%);transition:transform .2s ease-out;
 background:linear-gradient(170deg,rgba(3,105,161,.97),rgba(8,43,87,.98));border-left:1px solid var(--borda);overflow-y:auto;overscroll-behavior:contain;padding:16px 16px 40px;outline:none}
#dr.on{transform:none}
.dr-top{display:flex;justify-content:space-between;gap:10px;align-items:flex-start;margin-bottom:10px}
.dr-top h3{font-size:18px;line-height:1.3;font-weight:800}
.fechar{cursor:pointer;flex-shrink:0;width:38px;height:38px;border-radius:50%;border:1px solid var(--borda);background:var(--glass2);color:#fff;font-size:20px}
.linha-meta{font-size:12.5px;color:var(--sub);margin-bottom:10px;line-height:1.5}
.estado{display:inline-block;font-size:11px;font-weight:800;padding:4px 10px;border-radius:10px;background:rgba(103,232,249,.16);color:#a5f3fc;border:1px solid rgba(103,232,249,.3);margin-bottom:12px}
.estado.alerta{background:rgba(251,191,36,.18);color:var(--amarelo);border-color:rgba(251,191,36,.4)}
.artes{display:flex;gap:8px;overflow-x:auto;scroll-snap-type:x mandatory;margin-bottom:6px}
.moldura{flex:0 0 100%;aspect-ratio:4/5;border-radius:16px;border:1px solid var(--borda);scroll-snap-align:start;overflow:hidden;
 background:linear-gradient(110deg,rgba(255,255,255,.06) 30%,rgba(255,255,255,.16) 50%,rgba(255,255,255,.06) 70%);background-size:220% 100%;animation:brilho 1.3s linear infinite}
.moldura.ok{animation:none;background:rgba(0,0,0,.2)}
@keyframes brilho{to{background-position:-220% 0}}
.moldura img{width:100%;height:100%;object-fit:cover;display:block;opacity:0;transition:opacity .3s}
.semarte{border:1px dashed rgba(255,255,255,.3);border-radius:16px;padding:18px;text-align:center;color:var(--sub);font-size:13px;margin-bottom:12px}
.sec{margin-top:14px}
.sec h4{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:var(--ciano);margin-bottom:6px;font-weight:800}
.legtxt{white-space:pre-wrap;font-size:13px;line-height:1.5;max-height:42vh;overflow-y:auto;background:rgba(0,0,0,.2);border-radius:14px;padding:12px;overscroll-behavior:contain;word-break:break-word}
.mets{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}
.mets div{background:rgba(0,0,0,.18);border-radius:12px;padding:8px 10px;font-size:11px;color:var(--sub)}
.mets b{display:block;font-size:18px;color:#fff}
.decide{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}
.decide textarea{width:100%;min-height:54px;border-radius:12px;border:1px solid var(--borda);background:rgba(0,0,0,.2);color:#fff;font:13px Montserrat,system-ui,sans-serif;padding:8px}
.decide textarea::placeholder{color:var(--sub)}
#drmsg{font-size:12px;color:var(--verde);margin-top:8px;min-height:14px}
footer{text-align:center;font-size:11px;color:rgba(186,224,245,.6);margin-top:18px}
@media(max-width:760px){.duas{grid-template-columns:1fr}.frase{font-size:16.5px}.col{flex-basis:78vw}.dia{min-height:58px;padding:3px;border-radius:9px}
 .chip{font-size:0;height:8px;padding:0;border-radius:4px;margin-bottom:2px}.cal-grid{gap:3px}.hora{min-width:92px;font-size:12px}
 .tabela thead{display:none}.tabela tr{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid rgba(255,255,255,.12);padding:8px 0}
 .tabela td{border:none;padding:2px 4px}.tabela td.tt{grid-column:1/-1}.tabela td.num{text-align:left;font-size:12px}
 .tabela td.num::before{content:attr(data-l);display:block;font-size:9.5px;color:var(--sub);font-weight:700;text-transform:uppercase}}
</style></head><body>
<div class="glow g1"></div><div class="glow g2"></div>
<div class="wrap">
<header><div class="logo">cuidar<span>.vc</span> · painel da squad</div><div class="meta" id="meta">carregando</div></header>
<nav class="tabs" role="tablist">
 <button class="tab on" data-aba="hoje" role="tab">HOJE</button>
 <button class="tab" data-aba="calendario" role="tab">CALENDÁRIO</button>
 <button class="tab" data-aba="resultado" role="tab">RESULTADO</button>
</nav>
<div id="semtoken" class="card" style="display:none">Link incompleto: abra pelo endereço com a chave de acesso que o CMO enviou.</div>

<section class="painel on" id="p-hoje">
 <div class="card"><div class="frase" id="frase">Carregando o estado do dia</div></div>
 <div class="duas">
  <div class="card precisa"><h2>Precisa de você</h2><div id="precisa"></div></div>
  <div class="card"><h2>Vai ao ar nas próximas 24h</h2><div id="prox24"></div></div>
 </div>
 <div class="card" style="margin-top:12px"><h2>Esteira</h2><div class="esteira" id="esteira"></div></div>
 <div class="card"><h2>Agentes</h2><div class="faixa" id="faixa"></div><div id="acao-msg"></div></div>
</section>

<section class="painel" id="p-calendario">
 <div class="card">
  <div class="cal-head"><button class="seta" data-cal="-1" aria-label="mês anterior">‹</button><h2 id="cal-titulo">Calendário</h2><button class="seta" data-cal="1" aria-label="próximo mês">›</button></div>
  <div class="contador" id="cal-cont"></div>
  <div class="cal-grid" id="cal-grid"></div>
  <div class="legenda"><span><i style="background:rgba(52,211,153,.8)"></i>publicada</span><span><i style="background:rgba(96,165,250,.85)"></i>agendada</span><span><i style="background:rgba(148,163,184,.6)"></i>só pautada ou em produção</span><span>toque numa peça para ver</span></div>
 </div>
</section>

<section class="painel" id="p-resultado">
 <div class="kpis" id="kpis"></div>
 <div class="card"><h2>Seguidores do Instagram ao longo do tempo</h2><div id="serie"></div></div>
 <div class="card"><h2 id="tab-titulo">Posts publicados no mês</h2><div id="tabela"></div></div>
</section>
<footer id="rodape"></footer>
</div>

<div id="ov" hidden></div>
<aside id="dr" role="dialog" aria-modal="true" aria-label="Preview da peça" tabindex="-1"><div id="drc"></div></aside>

<script>
const K=new URLSearchParams(location.search).get('k')||'';
const MESES=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const MESES_MIN=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const $=id=>document.getElementById(id);
// esc() escapa TODO conteúdo interpolado em innerHTML; null e undefined viram texto vazio
const esc=s=>(s===0?'0':(s===null||s===undefined?'':String(s))).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>(v===null||v===undefined||v===''||!isFinite(Number(v)))?'sem dado':Number(v).toLocaleString('pt-BR');
const midia=m=>'media/'+encodeURIComponent(m)+'?k='+encodeURIComponent(K);
const plural=(n,um,varios)=>n===1?um:varios;
let S=null,P={},calA=0,calM=0,aberto=false,volta=null;

function trocaAba(a){
 document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('on',t.dataset.aba===a));
 document.querySelectorAll('.painel').forEach(p=>p.classList.toggle('on',p.id==='p-'+a));
 history.replaceState(null,'',location.pathname+location.search+'#'+a);
}

async function carrega(){
 if(!K){$('semtoken').style.display='block';return;}
 try{
  const r=await fetch('api/state?k='+encodeURIComponent(K));
  if(!r.ok){$('meta').textContent='não foi possível atualizar (código '+r.status+')';return;}
  S=await r.json();P=S.pecas||{};
  $('meta').textContent='atualizado '+S.gerado_em+' (Brasília)'+(S.zernio_ok?'':', Zernio sem resposta agora');
  renderHoje();
  if(!calA){const [y,m]=S.hoje.split('-').map(Number);calA=y;calM=m;}
  renderCal();renderRes();
  $('rodape').textContent='Todos os horários em Brasília. Fontes: arquivos da squad e Zernio.';
 }catch(e){$('meta').textContent='falha ao atualizar, tentando de novo em instantes';}
}

function renderHoje(){
 $('frase').textContent=S.frase;
 const pr=S.precisa||[];
 $('precisa').innerHTML=pr.length?pr.map(x=>{
  const clic=x.peca?' data-p="'+esc(x.peca)+'" tabindex="0" role="button"':'';
  const extra=(x.link?' <a class="lnk" href="'+esc(x.link)+'" target="_blank" rel="noopener noreferrer">abrir no Instagram</a>':'')
   +(x.alvo?' <button class="btn ok" data-decidir="resolvido" data-alvo="'+esc(x.alvo)+'">já resolvi</button>':'');
  return '<div class="item"'+clic+'><span class="tag">'+esc(x.tag)+'</span><div class="txt">'+esc(x.texto)
   +(x.meta?'<small>'+esc(x.meta)+'</small>':'')+(extra?'<div style="margin-top:6px">'+extra+'</div>':'')+'</div></div>';
 }).join(''):'<div class="vazio">Nada precisa de você agora</div>';
 const px=S.prox24||[];
 $('prox24').innerHTML=px.length?px.map(x=>'<div class="item" data-p="'+esc(x.peca)+'" tabindex="0" role="button"><span class="hora'+(x.quando.indexOf('a definir')>=0?' def':'')+'">'+esc(x.quando)+'</span><div class="txt"><b>'+esc(x.titulo)+'</b><small>'+esc(x.rede)+', '+esc(x.estado)+'</small></div></div>').join('')
  :'<div class="vazio">Nada programado para as próximas 24h</div>';
 $('esteira').innerHTML=(S.esteira||[]).map(c=>{
  const cards=c.ids.map(id=>{const p=P[id];if(!p)return '';
   const th=(p.imgs&&p.imgs.length)?'<div class="th"><img loading="lazy" alt="" src="'+midia(p.imgs[0])+'" onload="this.style.opacity=1"></div>':'';
   const d=p.hora&&p.etapa!=='publicada'?p.dia+' às '+p.hora:p.dia;
   return '<div class="pc'+(p.alerta?' alerta':'')+'" data-p="'+esc(id)+'" tabindex="0" role="button">'+th+'<div class="d">'+esc(d)+'</div><div class="t">'+esc(p.titulo)+'</div><div class="e">'+esc(p.estado)+'</div></div>';
  }).join('');
  return '<div class="col"><h3><span>'+esc(c.rotulo)+'</span><b>'+(c.ids.length+c.mais)+'</b></h3>'+(cards||'<div class="nada">nenhuma peça aqui</div>')
   +(c.mais?'<div class="mais">mais '+c.mais+' no calendário</div>':'')+'</div>';
 }).join('');
 $('faixa').innerHTML=(S.agentes||[]).map(a=>'<div class="ag"><span class="dot '+esc(a.cor)+'"></span><div><b>'+esc(a.nome)+'</b><div class="s">'+esc(a.status)+'</div>'
  +(a.proxima?'<div class="s">próxima '+esc(a.proxima)+'</div>':'')+'</div><button class="btn" data-rodar="'+a.i+'"'+(a.pode_rodar?'':' disabled')+'>rodar agora</button></div>').join('');
}

function tipoChip(p){return p.etapa==='publicada'?'c-pub':(p.etapa==='agendada'&&p.hora?'c-ag':'c-pa');}
function renderCal(){
 $('cal-titulo').textContent=MESES[calM-1]+' de '+calA;
 const pref=calA+'-'+String(calM).padStart(2,'0');
 const doMes=Object.values(P).filter(p=>p.data.slice(0,7)===pref&&p.estado!=='barrada por você');
 const nPub=doMes.filter(p=>p.etapa==='publicada').length,nAg=doMes.filter(p=>p.etapa==='agendada'&&p.hora).length;
 const nPa=doMes.filter(p=>p.etapa==='pauta').length,nProd=doMes.length-nPub-nAg-nPa;
 $('cal-cont').textContent=MESES_MIN[calM-1]+': '+nPub+' '+plural(nPub,'publicado','publicados')+', '+nAg+' '+plural(nAg,'agendado','agendados')+', '+nPa+' só '+plural(nPa,'pautado','pautados')+(nProd?', '+nProd+' em produção':'');
 const porDia={};doMes.forEach(p=>(porDia[p.data]=porDia[p.data]||[]).push(p));
 const ini=new Date(calA,calM-1,1).getDay(),dias=new Date(calA,calM,0).getDate();
 let h=['dom','seg','ter','qua','qui','sex','sáb'].map(d=>'<div class="dow">'+d+'</div>').join('');
 for(let i=0;i<ini;i++)h+='<div class="dia fora"></div>';
 for(let d=1;d<=dias;d++){
  const ds=pref+'-'+String(d).padStart(2,'0');
  const it=(porDia[ds]||[]).sort((a,b)=>(a.hora||'99').localeCompare(b.hora||'99'));
  h+='<div class="dia'+(ds===S.hoje?' hoje':'')+'"><div class="n">'+d+'</div>'+it.map(p=>'<button class="chip '+tipoChip(p)+(p.alerta?' alerta':'')+'" data-p="'+esc(p.id)+'" title="'+esc(p.titulo)+'">'+(p.hora&&p.etapa!=='pauta'?esc(p.hora)+' ':'')+esc(p.titulo)+'</button>').join('')+'</div>';
 }
 const resto=(7-((ini+dias)%7))%7;for(let i=0;i<resto;i++)h+='<div class="dia fora"></div>';
 $('cal-grid').innerHTML=h;
}
function calNav(d){calM+=d;if(calM>12){calM=1;calA++;}if(calM<1){calM=12;calA--;}renderCal();}

function renderRes(){
 const R=S.resultado||{},sg=R.seguidores||{},so=R.soma||{};
 const kpi=(rot,v,fonte)=>'<div class="card"><div class="rot">'+esc(rot)+'</div><div class="big'+(num(v)==='sem dado'?' sd':'')+'">'+esc(num(v))+'</div><div class="fonte">'+esc(fonte)+'</div></div>';
 const nPosts=(R.linhas||[]).length;
 $('kpis').innerHTML=kpi('Seguidores no Instagram',sg.valor,'Fonte: '+sg.fonte+(sg.atualizado?', atualizado '+sg.atualizado:''))
  +kpi('Alcance somado em '+R.mes,so.alcance,'Fonte: soma do alcance de cada post publicado no mês ('+nPosts+' '+plural(nPosts,'post','posts')+'), Zernio.')
  +kpi('Comentários em '+R.mes,so.comentarios,'Fonte: soma dos comentários por post no mês, Zernio.')
  +kpi('Cadastros vindos do conteúdo',null,'Ainda não existe fonte de cadastros com UTM conectada ao painel.');
 const se=R.serie||[];
 if(se.length<7){$('serie').innerHTML='<div class="vazio">ainda sem dados suficientes, precisa de pelo menos 7 dias de histórico</div>';}
 else{const w=600,h=140,pd=22,vs=se.map(p=>p.v),mx=Math.max(...vs),mn=Math.min(...vs),rg=(mx-mn)||1;
  const x=i=>pd+i*(w-2*pd)/(se.length-1),y=v=>h-pd-(v-mn)/rg*(h-2*pd);
  $('serie').innerHTML='<svg class="spark" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Seguidores por dia"><polyline points="'+se.map((p,i)=>x(i)+','+y(p.v)).join(' ')+'" fill="none" stroke="#67e8f9" stroke-width="2" stroke-linejoin="round"/>'
   +se.map((p,i)=>'<circle cx="'+x(i)+'" cy="'+y(p.v)+'" r="6" fill="transparent"><title>'+esc(p.d)+': '+esc(num(p.v))+'</title></circle>').join('')
   +'<text x="'+x(se.length-1)+'" y="'+(y(se[se.length-1].v)-8)+'" fill="#f0f9ff" font-size="12" font-weight="700" text-anchor="end">'+esc(num(se[se.length-1].v))+'</text>'
   +'<text x="'+pd+'" y="'+(h-4)+'" fill="#bae0f5" font-size="10">'+esc(se[0].d)+'</text><text x="'+(w-pd)+'" y="'+(h-4)+'" fill="#bae0f5" font-size="10" text-anchor="end">'+esc(se[se.length-1].d)+'</text></svg>';}
 $('tab-titulo').textContent='Posts publicados em '+R.mes;
 const L=R.linhas||[];
 const cel=(v,l)=>'<td class="num'+(num(v)==='sem dado'?' sd':'')+'" data-l="'+l+'">'+esc(num(v))+'</td>';
 $('tabela').innerHTML=L.length?'<table class="tabela"><thead><tr><th>Peça</th><th>Alcance</th><th>Curtidas</th><th>Comentários</th><th>Cadastros</th></tr></thead><tbody>'
  +L.map(l=>'<tr data-p="'+esc(l.peca)+'" tabindex="0" role="button"><td class="tt"><b>'+esc(l.titulo)+'</b><div class="meta">'+esc(l.quando)+(l.redes?', '+esc(l.redes):'')+'</div></td>'
   +cel(l.alcance,'alcance')+cel(l.curtidas,'curtidas')+cel(l.comentarios,'comentários')+cel(l.cadastros,'cadastros')+'</tr>').join('')+'</tbody></table>'
  :'<div class="vazio">Nenhuma peça publicada neste mês ainda</div>';
}

function htmlPeca(p){
 let h='<div class="dr-top"><h3>'+esc(p.titulo)+'</h3><button class="fechar" data-fechar aria-label="fechar">×</button></div>';
 const meta=[p.quando||(p.dia+', hora a definir')];
 if(p.redes&&p.redes.length)meta.push(p.redes.join(' e '));
 if(p.formato)meta.push(p.formato);
 h+='<div class="linha-meta">'+esc(meta.join(', '))+'</div><span class="estado'+(p.alerta?' alerta':'')+'">'+esc(p.estado)+'</span>';
 if(p.imgs&&p.imgs.length){
  h+='<div class="artes">'+p.imgs.map((m,i)=>'<div class="moldura"><img alt="arte da peça'+(p.imgs.length>1?', card '+(i+1):'')+'" '+(i?'loading="lazy" ':'')+'data-src="'+midia(m)+'" onload="this.style.opacity=1;this.parentNode.classList.add(\'ok\')"></div>').join('')+'</div>';
  h+='<div class="meta" style="margin-bottom:4px">'+(p.carrossel>1?'carrossel de '+p.carrossel+', deslize para ver os cards':'imagem única')+'</div>';
 }else{h+='<div class="semarte">Esta peça ainda não tem arte.</div>';}
 if(p.qc)h+='<div class="sec"><h4>QC</h4><div>'+(p.qc.aprovado?'Aprovado':'Reprovado'+(p.qc.motivo?'. Motivo: '+esc(p.qc.motivo):''))+'</div></div>';
 h+='<div class="sec"><h4>Legenda do Instagram</h4>'+(p.legenda_ig?'<div class="legtxt">'+esc(p.legenda_ig)+'</div>':'<div class="vazio">Legenda ainda não escrita.</div>')+'</div>';
 if(p.legenda_fb)h+='<div class="sec"><h4>Legenda do Facebook</h4><div class="legtxt">'+esc(p.legenda_fb)+'</div></div>';
 if(p.gancho||p.pilar||p.publico)h+='<div class="sec"><h4>Pauta</h4><div style="font-size:13px;line-height:1.5">'+(p.pilar?'<div>'+esc(p.pilar)+'</div>':'')+(p.gancho?'<div>Gancho: '+esc(p.gancho)+'</div>':'')+(p.publico?'<div>Público: '+esc(p.publico)+'</div>':'')+'</div></div>';
 if(p.etapa==='publicada'){
  const m=p.metricas||{};
  h+='<div class="sec"><h4>Métricas</h4><div class="mets"><div><b>'+esc(num(m.alcance))+'</b>alcance</div><div><b>'+esc(num(m.impressoes))+'</b>impressões</div><div><b>'+esc(num(m.curtidas))+'</b>curtidas</div><div><b>'+esc(num(m.comentarios))+'</b>comentários</div></div>'
   +((p.links||[]).length?'<div style="margin-top:8px;display:flex;gap:14px;flex-wrap:wrap">'+p.links.map(l=>'<a class="lnk" href="'+esc(l.url)+'" target="_blank" rel="noopener noreferrer">ver no '+esc(l.rede)+'</a>').join('')+'</div>':'')+'</div>';
 }
 if(p.decisao)h+='<div class="sec"><h4>Sua decisão</h4><div>'+esc(p.decisao)+'</div></div>';
 else if(p.pode&&p.pode.length){
  h+='<div class="sec"><h4>Decisão</h4><div class="decide"><textarea id="motivo" placeholder="motivo (opcional)"></textarea>'
   +(p.pode.indexOf('aprovar')>=0?'<button class="btn ok" data-decidir="aprovar" data-alvo="'+esc(p.id)+'">aprovar</button>':'')
   +(p.pode.indexOf('barrar')>=0?'<button class="btn no" data-decidir="barrar" data-alvo="'+esc(p.id)+'">barrar</button>':'')+'</div></div>';
 }
 return h+'<div id="drmsg"></div>';
}

function abrir(id,el){
 const p=P[id];if(!p)return;
 volta={y:window.scrollY,el:el,est:$('esteira').scrollLeft};
 $('drc').innerHTML=htmlPeca(p);
 $('ov').hidden=false;$('dr').classList.add('on');$('dr').scrollTop=0;aberto=true;
 $('dr').focus({preventScroll:true});
 // imagem pesada carrega depois da moldura aparecer
 requestAnimationFrame(()=>$('drc').querySelectorAll('img[data-src]').forEach(i=>{i.src=i.dataset.src;}));
}
function fechar(){
 if(!aberto)return;aberto=false;
 $('dr').classList.remove('on');$('ov').hidden=true;
 if(volta){window.scrollTo(0,volta.y);$('esteira').scrollLeft=volta.est;if(volta.el&&document.body.contains(volta.el))volta.el.focus({preventScroll:true});}
}

async function rodar(i,btn){
 btn.disabled=true;btn.textContent='disparando';
 try{const r=await fetch('api/acao?k='+encodeURIComponent(K),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({agente:Number(i)})});
  const j=await r.json();$('acao-msg').textContent=j.msg||'resposta sem mensagem';}
 catch(e){$('acao-msg').textContent='falha ao disparar, tente de novo';}
 setTimeout(carrega,5000);
}
async function decidir(dec,alvo,btn){
 const mo=$('motivo');
 document.querySelectorAll('[data-decidir]').forEach(b=>{if(b.dataset.alvo===alvo)b.disabled=true;});
 try{const r=await fetch('api/decisao?k='+encodeURIComponent(K),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({alvo:alvo,decisao:dec,motivo:mo&&aberto?mo.value:''})});
  const j=await r.json();
  if(aberto&&$('drmsg'))$('drmsg').textContent=j.msg||'';
  else $('acao-msg').textContent=j.msg||'';
  await carrega();
