class H(BaseHTTPRequestHandler):
    def log_message(self, fmt, *a):
        try:
            line = fmt % a
            line = re.sub(r"[?&]k=[^&\s]+", "k=***", line)
            print(f"[{datetime.now(BRT):%d/%m %H:%M:%S}] {line}", flush=True)
        except Exception:
            pass

    def _send(self, code, body, ctype="application/json; charset=utf-8", cache="no-store", extra=None):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Cache-Control", cache)
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header("X-Frame-Options", "DENY")
        for k, v in (extra or {}).items():
            self.send_header(k, v)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def _json(self, code, obj):
        return self._send(code, json.dumps(obj, ensure_ascii=False).encode())

    def _ok(self, q):
        k = q.get("k", [""])[0]
        if not k:
            return False
        return secrets.compare_digest(k, TOKEN)

    def _body(self):
        n = int(self.headers.get("Content-Length") or 0)
        if n > 20000:
            raise ValueError("grande demais")
        return json.loads(self.rfile.read(n).decode()) if n else {}

    def do_POST(self):
        u = urlparse(self.path)
        q = parse_qs(u.query)
        if u.path not in ("/api/acao", "/api/decisao"):
            return self._send(404, b'{"erro":"rota"}')
        if not self._ok(q):
            return self._send(403, b'{"erro":"token"}')
        try:
            body = self._body()
        except Exception:
            return self._send(400, b'{"erro":"json"}')
        if u.path == "/api/acao":
            return self._acao(body)
        return self._decisao(body)

    def _acao(self, body):
        try:
            idx = int(body.get("agente"))
            agente, nome_ag = AGENTS[idx]
            if idx < 0:
                raise IndexError
        except Exception:
            return self._json(400, {"ok": False, "msg": "agente fora da lista permitida"})
        job = _jobs().get(agente)
        if not job or not job.get("enabled", True):
            return self._json(400, {"ok": False, "msg": f"{nome_ag} não tem horário ativo no cron, não dá para disparar daqui."})
        # single-flight: um disparo por vez no painel inteiro, e nunca com o agente já rodando
        if not _run_lock.acquire(blocking=False):
            return self._json(200, {"ok": True, "msg": "Outro disparo está em andamento, tente em alguns segundos."})
        try:
            if time.time() - _disparos.get(agente, 0) < 120 or _rodando_agora(agente):
                return self._json(200, {"ok": True, "msg": f"{nome_ag} já está trabalhando agora, disparo ignorado."})
            logs = BASE / "logs"
            logs.mkdir(exist_ok=True)
            logf = logs / f"acao-{agente[:8]}-{datetime.now(BRT).strftime('%Y%m%d-%H%M%S')}.log"
            with open(logf, "wb") as fh:
                subprocess.Popen([HERMES, "-p", "cuidar", "cron", "run", agente],
                                 stdout=fh, stderr=subprocess.STDOUT, start_new_session=True)
            os.chmod(logf, 0o600)
            _disparos[agente] = time.time()
            with open(ACOES_LOG, "a") as fh:
                fh.write(json.dumps({"ts": datetime.now(BRT).isoformat(), "agente": agente,
                                     "acao": "rodar", "origem": "dashboard-novo"}, ensure_ascii=False) + "\n")
            os.chmod(ACOES_LOG, 0o600)
            return self._json(200, {"ok": True, "msg": f"{nome_ag} disparado. O resultado aparece na esteira em alguns minutos."})
        except Exception:
            return self._json(500, {"ok": False, "msg": "falha ao disparar o agente"})
        finally:
            _run_lock.release()

    def _decisao(self, body):
        alvo = str(body.get("alvo") or "")
        decisao = str(body.get("decisao") or "")
        motivo = re.sub(r"\s+", " ", str(body.get("motivo") or "")).strip()[:500]
        _, interno = get_state()
        info = interno["alvos"].get(alvo)
        if not info or decisao not in info["permitidas"]:
            return self._json(400, {"ok": False, "msg": "essa decisão não está disponível para este item agora"})
        agora = datetime.now(BRT)
        reg = {"ts": agora.isoformat(), "alvo": alvo, "tipo": info["tipo"], "decisao": decisao,
               "titulo": info["titulo"], "data_peca": info["data"], "motivo": motivo, "origem": "dashboard"}
        rot = {"aprovar": "APROVADO", "barrar": "BARRADO", "resolvido": "RESOLVIDO"}[decisao]
        try:
            with _decisao_lock:
                APROV_DIR.mkdir(parents=True, exist_ok=True)
                jl = APROV_DIR / "decisoes.jsonl"
                with open(jl, "a") as fh:
                    fh.write(json.dumps(reg, ensure_ascii=False) + "\n")
                md = APROV_DIR / f"aprovacoes-{agora.strftime('%Y-%m-%d')}.md"
                novo = not md.exists()
                with open(md, "a") as fh:
                    if novo:
                        fh.write(f"# Decisões do dono, {agora.strftime('%d/%m/%Y')} (painel)\n\n"
                                 "Formato: `- AAAA-MM-DD HH:MM | DECISÃO | data da peça | título | motivo`\n\n")
                    fh.write(f"- {agora.strftime('%Y-%m-%d %H:%M')} | {rot} | {info['data'] or 'sem data'} | "
                             f"{info['titulo']} | {motivo or 'sem motivo informado'}\n")
                for f in (jl, md):
                    os.chmod(f, 0o600)
        except Exception:
            return self._json(500, {"ok": False, "msg": "não consegui registrar a decisão, tente de novo"})
        get_state(forcar=True)
        msg = {"aprovar": "Aprovação registrada. A squad segue com a peça.",
               "barrar": "Peça barrada. A squad não vai publicar.",
               "resolvido": "Marcado como resolvido."}[decisao]
        return self._json(200, {"ok": True, "msg": msg})

    def do_GET(self):
        u = urlparse(self.path)
        q = parse_qs(u.query)
        if u.path == "/api/health":
            return self._send(200, b'{"ok":true}')
        if not self._ok(q):
            return self._send(403, b'{"erro":"token"}')
        if u.path == "/":
            return self._send(200, PAGE.encode(), "text/html; charset=utf-8")
        if u.path == "/api/state":
            return self._json(200, get_state()[0])
        if u.path.startswith("/media/"):
            mid = u.path[len("/media/"):]
            with _media_lock:
                alvo = _media.get(mid)
            if not alvo:
                return self._send(404, b'{"erro":"nao encontrado"}')
            if alvo.startswith("https://"):
                return self._send(302, b"", "text/plain", cache="private, max-age=600", extra={"Location": alvo})
            base = (SQUAD / "artes").resolve()
            arq = Path(alvo).resolve()
            if not arq.is_relative_to(base) or arq.suffix.lower() not in (".png", ".jpg", ".jpeg") or not arq.is_file():
                return self._send(404, b'{"erro":"nao encontrado"}')
            return self._send(200, arq.read_bytes(), "image/png" if arq.suffix.lower() == ".png" else "image/jpeg",
                              cache="private, max-age=3600")
        return self._send(404, b'{"erro":"rota"}')


if __name__ == "__main__":
    srv = ThreadingHTTPServer(("127.0.0.1", PORT), H)
    print(f"dashboard NOVO cuidar.vc na porta {PORT}", flush=True)
    srv.serve_forever()

