#!/usr/bin/env python3
"""Dashboard NOVO da Squad de Postagens cuidar.vc: HOJE, CALENDÁRIO e RESULTADO.
Servidor stdlib (zero dependências), single-file. Estilo oficial: gradiente azul + glassmorfismo.
Uso: DASH_PORT=8801 python3 dashboard-novo.py  → http://127.0.0.1:8801/?k=<token> (token em dashboard-token.txt)
Um fetch único de estado (/api/state); renderização toda no cliente.
"""
import json, os, re, threading, time, secrets, hashlib, subprocess, unicodedata
import urllib.request
from datetime import datetime, timezone, timedelta, date
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse, parse_qs

BASE = Path(__file__).resolve().parent
SQUAD = BASE.parent                      # /home/hermes/cuidarvc/squad
CRON_OUT = Path("/home/hermes/.hermes/profiles/cuidar/cron/output")  # absoluto: Path.home() aponta pro home do profile
JOBS_FILE = Path("/home/hermes/.hermes/profiles/cuidar/cron/jobs.json")
TOKEN_FILE = BASE / "dashboard-token.txt"
PORT = int(os.environ.get("DASH_PORT") or 8800)
API = "https://api.zernio.com"
BRT = timezone(timedelta(hours=-3))
HERMES = "/home/hermes/.local/share/uv/tools/hermes-agent/bin/hermes"
ACOES_LOG = BASE / "acoes.jsonl"
APROV_DIR = Path(os.environ.get("DASH_APROVACOES_DIR") or (SQUAD / "aprovacoes"))

# ids conferidos em cron/jobs.json (12/09): o CMO ativo é 8c20e6866ceb (9b7420a209aa está pausado);
# o Community não tem job no cron, o estado dele vem de community/estado.json
AGENTS = [
    ("9587d40be7e7", "Planejador"),
    ("7bd73f39264b", "Copywriter"),
    ("7ab152d68c07", "Artes"),
    ("9e68702df006", "QC"),
    ("d2fd43a7edcd", "Agendador"),
    ("30b5228c9aea", "Métricas"),
    ("b1c27fe585a1", "Community"),
    ("8c20e6866ceb", "CMO"),
]

if not TOKEN_FILE.exists():
    TOKEN_FILE.write_text(secrets.token_hex(16).strip() + "\n")
    os.chmod(TOKEN_FILE, 0o600)
TOKEN = TOKEN_FILE.read_text().strip()

_api_cache, _api_lock = {}, threading.Lock()
_state_cache, _state_lock = {"ts": 0, "data": None}, threading.Lock()
_build_lock = threading.Lock()
_run_lock = threading.Lock()
_disparos = {}
_decisao_lock = threading.Lock()
_media, _media_lock = {}, threading.Lock()

MESES = ["janeiro", "fevereiro", "março", "abril", "maio", "junho",
         "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"]
REDES = {"instagram": "Instagram", "facebook": "Facebook", "tiktok": "TikTok", "linkedin": "LinkedIn",
         "youtube": "YouTube", "threads": "Threads", "twitter": "X"}


def zernio(path, ttl=240):
    """GET na API Zernio com cache em memória (erros ficam 30s em cache)."""
    now = time.time()
    with _api_lock:
        hit = _api_cache.get(path)
        if hit:
            ts, data = hit
            efetivo = 30 if (isinstance(data, dict) and "_erro" in data) else ttl
            if now - ts < efetivo:
                return data
    try:
        hdr = (SQUAD / "zernio.hdr").read_text().strip()
        req = urllib.request.Request(f"{API}{path}", headers={"Authorization": hdr.replace("Authorization:", "").strip()})
        with urllib.request.urlopen(req, timeout=20) as r:
            data = json.loads(r.read().decode())
    except Exception as e:
        with _api_lock:
            _api_cache[path] = (now, {"_erro": str(e)})
        return {"_erro": str(e)}
    with _api_lock:
        _api_cache[path] = (now, data)
    return data


# ---------------------------------------------------------------- utilidades de texto e hora

def read_text(p, limit=60000):
    try:
        return Path(p).read_text(errors="replace")[:limit]
    except Exception:
        return ""


def latest_file(d):
    try:
        files = sorted(Path(d).glob("*.md"), key=lambda f: f.stat().st_mtime, reverse=True)
        return files[0] if files else None
    except Exception:
        return None


def norm(s):
    s = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode().lower()
    return re.sub(r"[^a-z0-9]+", " ", s).strip()


_STOP = {"de", "da", "do", "das", "dos", "e", "o", "a", "os", "as", "um", "uma", "para", "pra", "com",
         "que", "em", "no", "na", "por", "seu", "sua", "voce", "quem", "the"}


def _tok(s):
    return {w for w in norm(s).split() if len(w) > 2 and w not in _STOP}


def similar(a, b):
    na, nb = norm(a), norm(b)
    if not na or not nb:
        return False
    if na == nb:
        return True
    if min(len(na), len(nb)) >= 12 and (na in nb or nb in na):
        return True
    ta, tb = _tok(a), _tok(b)
    if not ta or not tb:
        return False
    inter = len(ta & tb)
    return inter >= 2 and inter / min(len(ta), len(tb)) >= 0.8


_RE_PATH = re.compile(r"(?:/home/\S+|(?:[\w.\-]+/)+[\w.\-]+\.(?:md|png|jpe?g|json|py|txt|log)\b"
                      r"|\b[\w.\-]+\.(?:md|png|jpe?g|json|py|txt|log)\b)")
_RE_HEX = re.compile(r"\b[0-9a-f]{24}\b|\b[0-9a-f]{12}\b|\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b")


def limpa(s):
    """Texto seguro para a tela: sem caminho de arquivo, id interno, markdown cru nem travessão."""
    s = str(s or "")
    s = re.sub(r"`([^`]*)`", lambda m: "" if (_RE_PATH.search(m.group(1)) or _RE_HEX.search(m.group(1))) else m.group(1), s)
    s = _RE_PATH.sub("", s)
    s = _RE_HEX.sub("", s)
    s = s.replace("**", "").replace("__", "")
    s = re.sub(r"(?m)^#{1,6}\s+", "", s)
    s = re.sub(r"[ \t]*—[ \t]*", ", ", s)
    s = s.replace("–", "-")
    s = re.sub(r"\(\s*[,;:]?\s*\)", "", s)
    s = re.sub(r",\s*,", ",", s)
    s = re.sub(r"[ \t]{2,}", " ", s)
    s = re.sub(r"[ \t]+([,.;:])", r"\1", s)
    s = re.sub(r"(?m)^[ \t]*,[ \t]*", "", s)
    s = re.sub(r"\n{3,}", "\n\n", s)
    return s.strip()


def fmt_dt(dt):
    """Formato único de horário na tela inteira: dd/mm às HH:MM (Brasília)."""
    return dt.astimezone(BRT).strftime("%d/%m às %H:%M") if dt else ""


def parse_iso(iso):
    try:
        return datetime.fromisoformat(str(iso).replace("Z", "+00:00")) if iso else None
    except Exception:
        return None


def hid(*partes):
    return hashlib.sha1("|".join(str(p) for p in partes).encode()).hexdigest()[:12]


def reg_media(alvo):
    mid = hashlib.sha1(str(alvo).encode()).hexdigest()[:16]
    with _media_lock:
        _media[mid] = alvo
    return mid


# ---------------------------------------------------------------- fontes de dados

def parse_pautas():
    out = []
    pdir = SQUAD / "pautas"
    for pf in sorted(pdir.glob("pauta-*.md")) if pdir.is_dir() else []:
        m = re.match(r"pauta-(\d{4})-(\d{2})-(\d{2})", pf.name)
        if not m:
            continue
        ano_f, mes_f = int(m.group(1)), int(m.group(2))
        txt = read_text(pf)
        for bloco in re.split(r"(?m)^### ", txt)[1:]:
            head, _, corpo = bloco.partition("\n")
            corpo = corpo.split("\n## ")[0]
            if not re.match(r"\d+\.", head):
                continue
            d = re.search(r"\b(\d{1,2})/(\d{2})\b", head)
            if not d:
                continue
            dia, mes = int(d.group(1)), int(d.group(2))
            ano = ano_f + (1 if mes < mes_f - 6 else 0)
            try:
                dt = date(ano, mes, dia)
            except ValueError:
                continue
            q = re.search(r'["“]([^"”]{4,140})["”]', head)
            if q:
                titulo = q.group(1)
            else:
                titulo = head.rsplit(": ", 1)[-1] if ": " in head else re.sub(r"^\d+\.\s*", "", head)
            titulo = re.sub(r"\s*\([^)]*\d{1,2}/\d{2}[^)]*\)", "", titulo)
            titulo = limpa(re.sub(r"\s*\([^)]*\)\s*$", "", titulo.split(" — ")[0])).strip(' "')
            cat = re.sub(r"^\d+\.\s*", "", head).split("(")[0].split("★")[0].strip(" :")
            pil = re.search(r"\((P(?:ilar\s*)?\d[^)]*)\)", head)

            def campo(nome):
                mm = re.search(r"\*\*" + nome + r":\*\*\s*(.+)", corpo)
                return limpa(mm.group(1)).strip('"“” ') if mm else ""
            formato = campo("Formato")
            formato = re.split(r"[:(]", formato)[0].strip() if formato else ""
            out.append({"data": dt, "titulo": titulo, "categoria": limpa(cat), "pilar": limpa(pil.group(1)) if pil else "",
                        "gancho": campo("Gancho"), "formato": formato, "publico": campo("Público")})
    return out


def _secao(txt, padrao):
    m = re.search(r"(?ms)^## [^\n]*" + padrao + r"[^\n]*\n(.*?)(?=^## |\Z)", txt)
    return m.group(1) if m else ""


def _legenda(bruto):
    linhas = []
    for ln in bruto.splitlines():
        s = ln.strip()
        if re.match(r"^\*\*[^*]+:\*\*\s*(\*[^*]*\*)?\s*$", s) or s in ("---",) or s.startswith("*Status"):
            continue
        linhas.append(ln.rstrip())
    return limpa("\n".join(linhas))


def parse_copys():
    out = []
    cdir = SQUAD / "copys"
    for cf in sorted(cdir.glob("copy-*.md")) if cdir.is_dir() else []:
        m = re.match(r"copy-(\d{4})-(\d{2})-(\d{2})", cf.name)
        if not m:
            continue
        txt = read_text(cf)
        assunto = _secao(txt, "Assunto")
        q = re.search(r'["“]([^"”]{4,140})["”]', assunto)
        if q:
            titulo = q.group(1)
        else:
            b = re.search(r"\*\*([^*]{4,140})\*\*", assunto)
            titulo = b.group(1) if b else ""
        fm = re.search(r"\*\*([^*]{3,80})\*\*", _secao(txt, "FORMATO"))
        ig = _legenda(_secao(txt, "Legenda completa"))
        fb = _legenda(_secao(txt, "FACEBOOK"))
        gancho = next((ln.strip() for ln in ig.splitlines() if ln.strip()), "")
        out.append({"data": date(int(m.group(1)), int(m.group(2)), int(m.group(3))), "titulo": limpa(titulo),
                    "formato": limpa(fm.group(1)) if fm else "", "ig": ig, "fb": fb, "gancho": gancho})
    return out


def parse_artes():
    out = []
    adir = SQUAD / "artes"
    try:
        pastas = sorted(d for d in adir.iterdir() if d.is_dir() and re.match(r"artes-\d{4}-\d{2}-\d{2}$", d.name))
    except Exception:
        pastas = []
    for d in pastas:
        y, mo, da = map(int, d.name[6:].split("-"))
        cards = sorted(d.glob("card-*.png"), key=lambda p: int(re.sub(r"\D", "", p.stem) or 0))
        imgs = cards
        if not imgs:
            ent = read_text(d / "ENTREGA.md")
            m = re.search(r"([\w\-]+\.png)[^\n]*usar esta", ent)
            if m and (d / m.group(1)).is_file():
                imgs = [d / m.group(1)]
            else:
                cand = [p for p in d.glob("*.png") if not re.search(r"foto|board|opcao|canva|crop|qc", p.name)]
                cand.sort(key=lambda p: p.stat().st_mtime, reverse=True)
                imgs = cand[:1]
        if imgs:
            out.append({"data": date(y, mo, da), "imgs": [reg_media(str(p)) for p in imgs], "carrossel": len(cards)})
    return out


def parse_qcs():
    out = []
    qdir = SQUAD / "qc"
    for qf in sorted(qdir.glob("qc-*.md")) if qdir.is_dir() else []:
        m = re.match(r"qc-(\d{4})-(\d{2})-(\d{2})\.md$", qf.name)
        if not m:
            continue
        txt = read_text(qf)
        v = re.search(r"veredito\**\s*:\s*\**\s*[^\w\s]*\s*(aprovad|reprovad|rejeitad|ajuste)", txt, re.I)
        if not v:
            continue
        aprovado = v.group(1).lower().startswith("aprov")
        motivo = ""
        if not aprovado:
            sec = _secao(txt, "Motivo")
            itens = re.findall(r"(?m)^\d+\.\s+\*\*(.+?)\*\*", sec)
            if itens:
                motivo = "; ".join(limpa(i).rstrip(":. ") for i in itens)
            else:
                linhas = [limpa(l) for l in (sec or txt.split(v.group(0), 1)[-1]).splitlines() if limpa(l)]
                motivo = " ".join(linhas[:3])
            motivo = motivo[:300]
        t = re.search(r'\*\*Post:\*\*\s*["“]([^"”]+)["”]', txt)
        out.append({"data": date(int(m.group(1)), int(m.group(2)), int(m.group(3))),
                    "aprovado": aprovado, "motivo": motivo, "titulo": t.group(1) if t else ""})
    return out


def parse_calendario_json():
    out = []
    cdir = SQUAD / "calendario"
    for jf in sorted(cdir.glob("post-*.json")) if cdir.is_dir() else []:
        try:
            d = json.loads(read_text(jf, 400000))
        except Exception:
            continue
        m = re.search(r"(\d{4})-(\d{2})-(\d{2})", jf.name)
        incid = []
        for k, v in d.items():
            if k.startswith("incidente") and isinstance(v, dict):
                incid.append({"chave": jf.name + k, "o_que": str(v.get("o_que") or ""), "mitigacao": str(v.get("mitigacao") or "")})
        out.append({"postId": d.get("postId"), "status": d.get("status"), "permalink": d.get("permalink_ig"),
                    "data": date(int(m.group(1)), int(m.group(2)), int(m.group(3))) if m else None,
                    "conteudo": ((d.get("raw") or {}).get("post") or {}).get("content") or "", "incidentes": incid})
    return out


def parse_escalacoes():
    out = []
    for linha in read_text(SQUAD / "community" / "escalacoes.md").splitlines():
        m = re.match(r"^-\s*\[ \]\s*(.+)$", linha.strip())
        if not m:
            continue
        partes = [x.strip() for x in m.group(1).split("|")]
        status = next((p for p in partes if p.lower().startswith("status")), "")
        if "resolvid" in status.lower():
            continue
        quando = ""
        try:
            quando = fmt_dt(datetime.strptime(partes[0], "%Y-%m-%d %H:%M").replace(tzinfo=BRT))
        except Exception:
            pass
        tag = partes[1].capitalize() if len(partes) > 1 else "Community"
        rede = REDES.get(partes[2].lower(), partes[2]) if len(partes) > 2 else ""
        quem = partes[3] if len(partes) > 3 else ""
        resumo = partes[4] if len(partes) > 4 else m.group(1)
        out.append({"tipo": "escalacao", "tag": limpa(tag), "texto": limpa(f"{quem}: {resumo}" if quem else resumo),
                    "meta": ", ".join(x for x in (rede, quando) if x)})
    return out


def ler_decisoes():
    dec = {}
    for ln in read_text(APROV_DIR / "decisoes.jsonl", 2_000_000).splitlines():
        try:
            j = json.loads(ln)
            dec[j["alvo"]] = j
        except Exception:
            continue
    return dec


# ---------------------------------------------------------------- agentes

def _rodando_agora(job_id, usar_arquivo=True):
    """Agente em execução: processo com o job_id na linha de comando OU arquivo de saída fresco (<10 min)."""
    try:
        out = subprocess.run(["pgrep", "-af", job_id], capture_output=True, text=True, timeout=5).stdout.strip()
        if out and "dashboard" not in out:
            return True
    except Exception:
        pass
    if usar_arquivo:
        try:
            f = latest_file(CRON_OUT / job_id)
            if f and time.time() - f.stat().st_mtime < 600:
                return True
        except Exception:
            pass
    return False


def _jobs():
    try:
        d = json.loads(JOBS_FILE.read_text())
        lst = d.get("jobs", d) if isinstance(d, dict) else d
        lst = lst if isinstance(lst, list) else list(lst.values())
        return {j.get("id"): j for j in lst if isinstance(j, dict)}
    except Exception:
        return {}


def _horas_cron(expr):
    try:
        mi, ho = expr.split()[:2]
        minuto = int(mi) if mi.isdigit() else 0
        if ho == "*":
            horas = list(range(24))
        elif ho.startswith("*/"):
            horas = list(range(0, 24, int(ho[2:])))
        else:
            horas = []
            for p in ho.split(","):
                if "-" in p:
                    a, b = p.split("-")
                    horas += list(range(int(a), int(b) + 1))
                else:
                    horas.append(int(p))
        return minuto, sorted(set(horas))
    except Exception:
        return 0, []


def agentes_state(agora):
    jobs = _jobs()
    agora_utc = agora.astimezone(timezone.utc)
    out = []
    for idx, (job_id, nome) in enumerate(AGENTS):
        job = jobs.get(job_id)
        last_ts = None
        f = latest_file(CRON_OUT / job_id)
        if f:
            last_ts = f.stat().st_mtime
        if nome == "Community":
            try:
                com = json.loads((SQUAD / "community" / "estado.json").read_text())
                dt = parse_iso(com.get("atualizado_em"))
                last_ts = dt.timestamp() if dt else last_ts
            except Exception:
                pass
        ultima = fmt_dt(datetime.fromtimestamp(last_ts, BRT)) if last_ts else ""
        habilitado = bool(job and job.get("enabled", True))
        expr = ""
        if job:
            sch = job.get("schedule")
            expr = sch.get("expr", "") if isinstance(sch, dict) else str(sch or "")
        minuto, horas = _horas_cron(expr) if expr else (0, [])
        rodando = habilitado and _rodando_agora(job_id, usar_arquivo=False)
        ultimo_slot = proximo = None
        if horas:
            slots = []
            for dd in (-1, 0, 1):
                base = (agora_utc + timedelta(days=dd)).replace(minute=minuto, second=0, microsecond=0)
                slots += [base.replace(hour=h) for h in horas]
            passados = [s for s in slots if s <= agora_utc]
            futuros = [s for s in slots if s > agora_utc]
            ultimo_slot = max(passados) if passados else None
            proximo = min(futuros) if futuros else None
        if rodando:
            cor, txt = "azul", "trabalhando agora"
        elif not job:
            if last_ts and time.time() - last_ts < 4 * 3600:
                cor, txt = "verde", f"ativo, última checagem {ultima}"
            else:
                cor, txt = "cinza", "sem horário no cron"
        elif not habilitado:
            cor, txt = "cinza", "pausado no cron"
        elif ultimo_slot and last_ts and last_ts >= ultimo_slot.timestamp() - 300:
            cor, txt = "verde", f"rodou {ultima}"
        elif ultimo_slot and (agora_utc - ultimo_slot).total_seconds() < 45 * 60:
            cor, txt = "cinza", f"aguardando horário ({fmt_dt(ultimo_slot)})"
        elif ultimo_slot:
            cor, txt = "amarelo", f"não rodou {fmt_dt(ultimo_slot)}"
        else:
            cor, txt = "cinza", "aguardando horário"
        out.append({"i": idx, "nome": nome, "cor": cor, "status": txt,
                    "ultima": ultima, "proxima": fmt_dt(proximo) if (proximo and habilitado) else "",
                    "pode_rodar": habilitado and not rodando})
    return out


# ---------------------------------------------------------------- montagem das peças

def build_state():
    agora = datetime.now(BRT)
    hoje = agora.date()
    amanha = hoje + timedelta(days=1)
    decisoes = ler_decisoes()
    pecas = []

    def nova(d, titulo):
        p = {"data": d, "titulo": titulo, "titulos": [titulo], "pauta": None, "copy": None, "arte": None,
             "qc": None, "post": None}
        pecas.append(p)
        return p

    def acha(d, *textos):
        cands = [p for p in pecas if p["data"] == d]
        for t in textos:
            if not t:
                continue
            for p in cands:
                if any(similar(t, x) for x in p["titulos"]):
                    return p
        return None

    # 1. pautas (as mais novas completam as antigas)
    for it in parse_pautas():
        p = acha(it["data"], it["titulo"]) or nova(it["data"], it["titulo"])
        velho = p["pauta"] or {}
        p["pauta"] = {k: (it[k] or velho.get(k, "")) for k in ("categoria", "pilar", "gancho", "formato", "publico")}

    # 2. copys
    for c in parse_copys():
        p = acha(c["data"], c["titulo"], c["gancho"])
        if not p:
            livres = [x for x in pecas if x["data"] == c["data"] and not x["copy"]]
            p = livres[0] if len(livres) == 1 else nova(c["data"], c["titulo"] or c["gancho"][:80])
        p["copy"] = c
        p["titulos"] += [c["titulo"], c["gancho"]]

    def peca_do_dia(d, titulo=""):
        cands = [x for x in pecas if x["data"] == d]
        if titulo:
            achou = acha(d, titulo)
            if achou:
                return achou
        com_copy = [x for x in cands if x["copy"]]
        if com_copy:
            return com_copy[0]
        return cands[0] if len(cands) == 1 else None

    # 3. artes e 4. QC: pertencem à peça do dia (a que tem copy naquela data)
    for a in parse_artes():
        p = peca_do_dia(a["data"])
        if p:
            p["arte"] = a
    for q in parse_qcs():
        p = peca_do_dia(q["data"], q["titulo"])
        if p:
            p["qc"] = q

    # 5. posts reais (Zernio) + registros locais do Agendador
    cal_json = parse_calendario_json()
    permalink_por_post = {c["postId"]: c["permalink"] for c in cal_json if c.get("postId")}
    resp = zernio("/v1/posts?limit=50")
    api_ok = "_erro" not in resp
    post_para_peca = {}
    brutos = resp.get("posts", []) if api_ok else []
    if not api_ok:  # fallback: o que o Agendador registrou localmente
        for c in cal_json:
            if c.get("postId") and c.get("data") and c.get("status"):
                brutos.append({"_id": c["postId"], "status": c["status"], "content": c.get("conteudo") or "",
                               "scheduledFor": None, "_data_local": c["data"], "platforms": [], "mediaItems": []})
    for bp in brutos:
        dt = parse_iso(bp.get("scheduledFor"))
        d = dt.astimezone(BRT).date() if dt else bp.get("_data_local")
        if not d:
            continue
        conteudo = bp.get("content") or ""
        primeira = next((ln.strip() for ln in conteudo.splitlines() if ln.strip()), "")
        redes, links, falhas, pub_dts, fb = [], [], [], [], ""
        for pl in bp.get("platforms") or []:
            nome = REDES.get(pl.get("platform"), str(pl.get("platform") or "").capitalize())
            redes.append(nome)
            if pl.get("platformPostUrl"):
                links.append({"rede": nome, "url": pl["platformPostUrl"]})
            if pl.get("status") in ("failed", "error"):
                falhas.append(nome)
            if pl.get("publishedAt"):
                pub_dts.append(parse_iso(pl["publishedAt"]))
            if pl.get("platform") == "facebook" and pl.get("customContent"):
                fb = pl["customContent"]
        if not links and permalink_por_post.get(bp.get("_id")):
            links.append({"rede": "Instagram", "url": permalink_por_post[bp["_id"]]})
        status = bp.get("status") or ""
        publicado = status == "published" or bool(pub_dts)
        metricas = None
        if publicado and bp.get("_id"):
            an = zernio(f"/v1/analytics?postId={bp['_id']}", ttl=900)
            m = an.get("analytics") if isinstance(an, dict) else None
            if isinstance(m, dict):
                metricas = {"alcance": m.get("reach"), "curtidas": m.get("likes"),
                            "comentarios": m.get("comments"), "impressoes": m.get("impressions")}
        imgs = [reg_media(mi["url"]) for mi in (bp.get("mediaItems") or []) if mi.get("url") and mi.get("type", "image") == "image"]
        post = {"status": status, "publicado": publicado, "agendado_dt": dt,
                "publicado_dt": max(x for x in pub_dts if x) if any(pub_dts) else None,
                "redes": redes, "links": links, "falhas": falhas, "conteudo": conteudo, "fb": fb,
                "metricas": metricas, "imgs": imgs}
        p = acha(d, primeira, conteudo[:300])
        if not p or p["post"]:
            p = nova(d, re.split(r"(?<=[.!?])\s", primeira, 1)[0][:120] or "Post sem título")
        p["post"] = post
        p["titulos"].append(primeira)
        post_para_peca[bp.get("_id")] = p

    # ---------- estado de cada peça
    publicos = {}
    alvos = {}
    for p in pecas:
        pid = hid(p["data"].isoformat(), norm(p["titulos"][0]))
        p["id"] = pid
        dec = decisoes.get(pid)
        post, qc, copy, arte = p["post"], p["qc"], p["copy"], p["arte"]
        alerta, pode = False, []
        if post and post["publicado"]:
            etapa = "publicada"
            estado = f"publicada {fmt_dt(post['publicado_dt'] or post['agendado_dt'])}"
            if post["falhas"]:
                estado += f", falhou no {' e '.join(post['falhas'])}"
                alerta = True
        elif post and post["status"] in ("failed", "partial", "error"):
            etapa, estado, alerta, pode = "agendada", "falhou na publicação", True, ["aprovar", "barrar"]
        elif post and post["status"] == "scheduled":
            etapa = "agendada"
            if post["agendado_dt"] and (agora - post["agendado_dt"]).total_seconds() > 3600:
                estado, alerta, pode = f"passou do horário ({fmt_dt(post['agendado_dt'])}) e segue agendada", True, ["barrar"]
            else:
                estado, pode = f"vai ao ar {fmt_dt(post['agendado_dt'])}", ["barrar"]
        elif post:
            etapa, estado = "agendada", "rascunho no Zernio, sem horário"
        elif qc and not qc["aprovado"]:
            curto = qc["motivo"].split(";")[0][:90] if qc["motivo"] else "sem motivo registrado"
            etapa, estado, alerta, pode = "qc", f"devolvida: {curto}", True, ["aprovar", "barrar"]
        elif qc:
            etapa, estado = "qc", "aprovada, aguardando agendamento"
        elif arte:
            etapa, estado = "arte", "aguardando QC"
        elif copy:
            etapa, estado = "copy", "aguardando arte"
        else:
            etapa, estado = "pauta", "aguardando copy"
        if not (post and post["publicado"]) and p["data"] < hoje and not (post and post["status"] == "scheduled"):
            estado = "incompleta, " + estado
        if dec:
            rot = {"aprovar": "aprovada", "barrar": "barrada", "resolvido": "resolvida"}.get(dec.get("decisao"), "decidida")
            quando = fmt_dt(parse_iso(dec.get("ts")))
            dec_txt = f"{rot} por você {quando}"
            if dec.get("decisao") == "barrar" and etapa != "publicada":
                estado, alerta = "barrada por você", False
            elif dec.get("decisao") == "aprovar" and alerta:
                estado, alerta = "aprovada por você, aguardando a squad", False
            pode = []
        else:
            dec_txt = ""
        if etapa == "publicada":
            pode = []
        titulo = limpa(p["titulos"][0]) or "Peça sem título"
        legenda_ig = limpa(post["conteudo"]) if (post and post["conteudo"]) else (copy["ig"] if copy else "")
        legenda_fb = limpa(post["fb"]) if (post and post["fb"]) else (copy["fb"] if copy else "")
        imgs = arte["imgs"] if arte else (post["imgs"] if post else [])
        n_car = arte["carrossel"] if arte else (len(imgs) if len(imgs) > 1 else 0)
        pauta = p["pauta"] or {}
        formato = (copy or {}).get("formato") or pauta.get("formato") or ""
        pub = {
            "id": pid, "data": p["data"].isoformat(), "dia": p["data"].strftime("%d/%m"),
            "titulo": titulo, "etapa": etapa, "estado": limpa(estado), "alerta": alerta,
            "hora": post["agendado_dt"].astimezone(BRT).strftime("%H:%M") if (post and post["agendado_dt"]) else "",
            "quando": fmt_dt(post["publicado_dt"] or post["agendado_dt"]) if post else "",
            "redes": post["redes"] if post else [],
            "imgs": imgs, "carrossel": n_car,
            "legenda_ig": legenda_ig, "legenda_fb": legenda_fb,
            "qc": {"aprovado": qc["aprovado"], "motivo": qc["motivo"]} if qc else None,
            "gancho": pauta.get("gancho", ""), "pilar": " ".join(x for x in (pauta.get("categoria"), pauta.get("pilar") and f"({pauta['pilar']})") if x),
            "publico": pauta.get("publico", ""), "formato": formato,
            "metricas": post["metricas"] if (post and post["publicado"]) else None,
            "links": post["links"] if (post and post["publicado"]) else [],
            "pode": pode, "decisao": dec_txt,
            "pub_ts": (post["publicado_dt"] or post["agendado_dt"]).timestamp() if (post and post["publicado"] and (post["publicado_dt"] or post["agendado_dt"])) else None,
            "ag_ts": post["agendado_dt"].timestamp() if (post and post["agendado_dt"]) else None,
        }
        publicos[pid] = pub
        if pode:
            alvos[pid] = {"tipo": "peca", "titulo": titulo, "data": pub["dia"], "permitidas": pode}

    # ---------- PRECISA DE VOCÊ (só decisão humana)
    precisa = parse_escalacoes()
    for pub in sorted(publicos.values(), key=lambda x: x["data"]):
        if not pub["alerta"] or not pub["pode"]:
            continue
        if pub["etapa"] == "qc" and date.fromisoformat(pub["data"]) < hoje - timedelta(days=1):
            continue  # devolução antiga já saiu da janela de decisão
        tag = "Qualidade" if pub["etapa"] == "qc" else "Publicação"
        precisa.append({"tipo": "peca", "tag": tag, "texto": f"{pub['titulo']}: {pub['estado']}", "peca": pub["id"],
                        "meta": pub["dia"]})
    for c in cal_json:
        p = post_para_peca.get(c.get("postId"))
        for inc in c["incidentes"]:
            if "PENDENTE" not in inc["mitigacao"].upper():
                continue
            alvo = hid("incidente", inc["chave"])
            if alvo in decisoes:
                continue
            tit = publicos[p["id"]]["titulo"] if p else "post"
            if "duplicad" in (inc["o_que"] + inc["mitigacao"]).lower():
                texto = f"Post duplicado de \"{tit}\" continua no ar no Instagram e precisa ser apagado à mão (a API não apaga)."
            else:
                texto = f"Incidente de publicação em \"{tit}\" tem uma pendência manual."
            urls = re.findall(r"https://www\.instagram\.com/p/[\w\-]+/?", inc["mitigacao"])
            precisa.append({"tipo": "incidente", "tag": "Publicação", "texto": texto, "alvo": alvo,
                            "link": urls[-1] if urls else "", "peca": p["id"] if p else "",
                            "meta": publicos[p["id"]]["dia"] if p else ""})
            alvos[alvo] = {"tipo": "incidente", "titulo": texto, "data": "", "permitidas": ["resolvido"]}

    # ---------- VAI AO AR NAS PRÓXIMAS 24H
    prox = []
    lim = agora + timedelta(hours=24)
    for pub in publicos.values():
        if pub["estado"] == "barrada por você" or pub["etapa"] == "publicada":
            continue
        if pub["ag_ts"] and pub["etapa"] == "agendada":
            dt = datetime.fromtimestamp(pub["ag_ts"], BRT)
            if agora - timedelta(hours=1) <= dt <= lim:
                prox.append((0, pub["ag_ts"], {"peca": pub["id"], "quando": fmt_dt(dt), "titulo": pub["titulo"],
                                                "rede": " e ".join(pub["redes"]) or "rede a definir", "estado": pub["estado"]}))
        elif not pub["ag_ts"] and pub["data"] in (hoje.isoformat(), amanha.isoformat()):
            prox.append((1, pub["data"], {"peca": pub["id"], "quando": f"{pub['dia']}, hora a definir", "titulo": pub["titulo"],
                                           "rede": "rede a definir", "estado": pub["estado"]}))
    prox = [x[2] for x in sorted(prox, key=lambda x: (x[0], str(x[1])))]

    # ---------- frase de estado
    pub_hoje = [x for x in publicos.values() if x["pub_ts"] and datetime.fromtimestamp(x["pub_ts"], BRT).date() == hoje]
    ag_prox = sorted([x for x in publicos.values() if x["etapa"] == "agendada" and x["ag_ts"]
                      and agora.timestamp() <= x["ag_ts"] <= lim.timestamp() and x["estado"] != "barrada por você"],
                     key=lambda x: x["ag_ts"])
    n = len(pub_hoje)
    a = "nenhuma peça publicada hoje" if n == 0 else (f"1 peça publicada hoje" if n == 1 else f"{n} peças publicadas hoje")
    if not ag_prox:
        b = "nada agendado nas próximas 24h"
    elif len(ag_prox) == 1:
        b = f"1 agendada para {fmt_dt(datetime.fromtimestamp(ag_prox[0]['ag_ts'], BRT))}"
    else:
        b = f"{len(ag_prox)} agendadas, a próxima {fmt_dt(datetime.fromtimestamp(ag_prox[0]['ag_ts'], BRT))}"
    v = len(precisa)
    c = "nada travado aguardando você" if v == 0 else (f"1 item aguardando você" if v == 1 else f"{v} itens aguardando você")
    frase = f"{a[0].upper() + a[1:]}, {b} e {c}."

    # ---------- esteira (6 etapas)
    def ordem(x):
        return (x["data"], x["hora"])
    cols = []
    janela = (hoje - timedelta(days=3)).isoformat()
    for chave, rotulo in (("pauta", "Pauta"), ("copy", "Copy"), ("arte", "Arte"), ("qc", "QC"),
                          ("agendada", "Agendada"), ("publicada", "Publicada")):
        lst = [x for x in publicos.values() if x["etapa"] == chave]
        if chave == "pauta":
            lst = sorted([x for x in lst if x["data"] >= (hoje - timedelta(days=1)).isoformat()], key=ordem)
        elif chave == "publicada":
            lst = sorted(lst, key=lambda x: x["pub_ts"] or 0, reverse=True)
            lst = [x for x in lst if x["data"] >= janela] or lst[:1]
        else:
            lst = sorted([x for x in lst if x["data"] >= janela or x["etapa"] == "agendada"], key=ordem)
        limite = 6
        cols.append({"rotulo": rotulo, "ids": [x["id"] for x in lst[:limite]], "mais": max(len(lst) - limite, 0)})

    # ---------- RESULTADO
    contas = zernio("/v1/accounts")
    ig = next((x for x in contas.get("accounts", []) if x.get("platform") == "instagram"), None) if "_erro" not in contas else None
    seguidores = {"valor": None, "fonte": "sem conexão com o Zernio agora", "atualizado": ""}
    serie = []
    if ig:
        seguidores = {"valor": ig.get("followersCount"),
                      "fonte": f"conta @{ig.get('username') or 'instagram'} no Instagram, via Zernio",
                      "atualizado": fmt_dt(parse_iso(ig.get("followersLastUpdated")))}
        hist = zernio(f"/v1/analytics/instagram/follower-history?accountId={ig.get('_id')}", ttl=900)
        try:
            fh = hist.get("follower_count") if isinstance(hist.get("follower_count"), dict) else {}
            pts = fh.get("data") or hist.get("data") or hist.get("history") or []
            for pt in pts:
                dd = str(pt.get("date") or pt.get("day") or "")[:10]
                val = pt.get("value", pt.get("count"))
                if dd and val is not None:
                    serie.append({"d": f"{dd[8:10]}/{dd[5:7]}", "v": int(val)})
        except Exception:
            serie = []
    mes_chave = hoje.strftime("%Y-%m")
    linhas = []
    for x in sorted(publicos.values(), key=lambda x: x["pub_ts"] or 0, reverse=True):
        if not x["pub_ts"] or datetime.fromtimestamp(x["pub_ts"], BRT).strftime("%Y-%m") != mes_chave:
            continue
        m = x["metricas"] or {}
        linhas.append({"peca": x["id"], "quando": x["quando"], "titulo": x["titulo"], "redes": " e ".join(x["redes"]),
                       "alcance": m.get("alcance"), "curtidas": m.get("curtidas"), "comentarios": m.get("comentarios"),
                       "cadastros": None})

    def soma(k):
        vals = [l[k] for l in linhas if isinstance(l[k], (int, float))]
        return sum(vals) if vals else None

    publico = {
        "gerado_em": fmt_dt(agora),
        "hoje": hoje.isoformat(), "mes_nome": MESES[hoje.month - 1],
        "zernio_ok": api_ok,
        "frase": frase,
        "precisa": precisa,
        "prox24": prox,
        "esteira": cols,
        "agentes": agentes_state(agora),
        "pecas": publicos,
        "resultado": {"seguidores": seguidores, "serie": serie if len(serie) >= 7 else [],
                      "mes": MESES[hoje.month - 1], "linhas": linhas,
                      "soma": {"alcance": soma("alcance"), "curtidas": soma("curtidas"), "comentarios": soma("comentarios")}},
    }
    return publico, {"alvos": alvos}


def get_state(forcar=False):
    with _state_lock:
        if not forcar and _state_cache["data"] and time.time() - _state_cache["ts"] < 60:
            return _state_cache["data"]
    with _build_lock:
        with _state_lock:
            if not forcar and _state_cache["data"] and time.time() - _state_cache["ts"] < 60:
                return _state_cache["data"]
        data = build_state()
        with _state_lock:
            _state_cache.update(ts=time.time(), data=data)
        return data


