async function carrega(){
 if(!K){$('semtoken').style.display='block';return;}
 try{
  const r=await fetch('api/state?k='+encodeURIComponent(K));
  if(!r.ok){$('meta').textContent='não foi possível atualizar (código '+r.status+')';return;}
  S=await r.json();P=S.pecas||{};
  $('meta').textContent='atualizado '+S.gerado_em+' (Brasília)'+(S.zernio_ok?'':', Zernio sem resposta agora');
