  if(!calA){const [y,m]=S.hoje.split('-').map(Number);calA=y;calM=m;}
  renderCal();renderRes();
  $('rodape').textContent='Todos os horários em Brasília. Fontes: arquivos da squad e Zernio.';
 }catch(e){$('meta').textContent='falha ao atualizar, tentando de novo em instantes';}
}

