const {spawn} = require('child_process');
const fs = require('fs');
const base = '/home/hermes/.cache/ms-playwright/chromium_headless_shell-1234/';
const dir = fs.readdirSync(base).find(d => fs.statSync(base + d).isDirectory());
const BIN = base + dir + '/chrome-headless-shell';
const TOKEN = fs.readFileSync('/home/hermes/cuidarvc/squad/dashboard/dashboard-token.txt', 'utf8').trim();
const URL0 = 'http://127.0.0.1:8801/?k=' + TOKEN;
const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  const chrome = spawn(BIN, ['--headless', '--no-sandbox', '--disable-gpu', '--remote-debugging-port=9333',
    '--user-data-dir=/tmp/cdp-prof-novo', 'about:blank'], {stdio: 'ignore'});
  let alvo;
  for (let i = 0; i < 40 && !alvo; i++) {
    await sleep(250);
    try { alvo = (await (await fetch('http://127.0.0.1:9333/json/list')).json()).find(t => t.type === 'page'); } catch (e) {}
  }
  const ws = new WebSocket(alvo.webSocketDebuggerUrl);
  await new Promise(r => ws.onopen = r);
  let seq = 0; const pend = {};
  ws.onmessage = m => { const j = JSON.parse(m.data); if (j.id && pend[j.id]) { pend[j.id](j); delete pend[j.id]; } };
  const cdp = (method, params = {}) => new Promise(r => { const id = ++seq; pend[id] = r; ws.send(JSON.stringify({id, method, params})); });
  const ev = async expr => { const r = await cdp('Runtime.evaluate', {expression: expr, awaitPromise: true, returnByValue: true});
    if (r.result.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails)); return r.result.result.value; };
  const shot = async nome => { const r = await cdp('Page.captureScreenshot', {format: 'png'}); fs.writeFileSync('/tmp/' + nome + '.png', Buffer.from(r.result.data, 'base64')); };

  await cdp('Page.enable'); await cdp('Runtime.enable');
  await cdp('Emulation.setDeviceMetricsOverride', {width: 390, height: 844, deviceScaleFactor: 1, mobile: true});
  const t0 = Date.now();
  await cdp('Page.navigate', {url: URL0});
  for (let i = 0; i < 60; i++) { await sleep(250); if (await ev("!!(window.S)")) break; }
  const out = {carregou_ms: Date.now() - t0};
  await sleep(1500);
  out.frase = await ev("document.getElementById('frase').innerText");
  out.precisa = await ev("document.getElementById('precisa').innerText");
  out.prox24 = await ev("document.getElementById('prox24').innerText");
  out.largura_doc_390 = await ev("document.documentElement.scrollWidth");
  await shot('novo-hoje-390');

  // texto visível de todas as abas
  const proibido = "/(undefined|NaN|\\bnull\\b|\\bNone\\b|—|\\/home\\/|\\.md\\b|\\.png\\b|\\.json\\b|\\b[0-9a-f]{24}\\b|\\*\\*)/";
  out.textos_proibidos = await ev(`(()=>{const achados=[];['hoje','calendario','resultado'].forEach(a=>{trocaAba(a);const t=document.getElementById('p-'+a).innerText;const m=t.match(${proibido}g);if(m)achados.push(a+': '+m.join(','));});trocaAba('hoje');return achados;})()`);
  // formatos de horário: todo dd/mm seguido de hora deve ser 'dd/mm às HH:MM'
  out.horarios_fora_do_padrao = await ev(`(()=>{let t='';['hoje','calendario','resultado'].forEach(a=>{trocaAba(a);t+=document.getElementById('p-'+a).innerText+'\\n';});trocaAba('hoje');
    return (t.match(/\\d{2}\\/\\d{2}\\D{1,6}\\d{1,2}[:h]\\d{0,2}/g)||[]).filter(x=>!/^\\d{2}\\/\\d{2} às \\d{2}:\\d{2}$/.test(x));})()`);

  // preview a partir das 3 abas, Esc fecha e volta ao mesmo lugar
  out.preview = {};
  for (const [aba, sel] of [['hoje', '#esteira [data-p]'], ['calendario', '#cal-grid [data-p]'], ['resultado', '#tabela [data-p]']]) {
    const r = await ev(`(async()=>{trocaAba('${aba}');window.scrollTo(0,0);await new Promise(r=>setTimeout(r,50));
      const els=[...document.querySelectorAll('${sel}')];const el=els[els.length-1];if(!el)return {erro:'sem elemento clicável'};
      window.scrollTo(0,Math.min(250,document.documentElement.scrollHeight-innerHeight));await new Promise(r=>setTimeout(r,50));
      const y0=scrollY;const t=performance.now();el.click();const aberto=document.getElementById('dr').classList.contains('on');const ms=performance.now()-t;
      const txt=document.getElementById('drc').innerText.slice(0,160);const temImg=!!document.querySelector('#drc img');const botoes=document.querySelectorAll('#drc [data-decidir]').length;
      await new Promise(r=>setTimeout(r,400));
      document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
      await new Promise(r=>setTimeout(r,100));
      return {clicaveis:els.length,aberto,abrir_ms:Math.round(ms),fechou:!document.getElementById('dr').classList.contains('on'),mesmo_scroll:scrollY===y0,y0,y1:scrollY,
        aba_mantida:document.getElementById('p-${aba}').classList.contains('on'),temImg,botoes,txt};})()`);
    out.preview[aba] = r;
  }
  // peça só pautada: nenhuma imagem
  out.pautada = await ev(`(()=>{trocaAba('hoje');const id=Object.values(P).find(p=>p.etapa==='pauta').id;abrir(id,null);
    const r={img:!!document.querySelector('#drc img'),aviso:document.getElementById('drc').innerText.includes('ainda não tem arte'),
    thumb_esteira:!!document.querySelector('#esteira [data-p="'+id+'"] img')};fechar();return r;})()`);
  // peça publicada: sem botões, com métricas e link
  out.publicada = await ev(`(()=>{const id=Object.values(P).find(p=>p.etapa==='publicada').id;abrir(id,null);
    const r={botoes:document.querySelectorAll('#drc [data-decidir]').length,metricas:document.getElementById('drc').innerText.includes('alcance'),link:!!document.querySelector('#drc a.lnk')};return r;})()`);
  await sleep(1500);
  await shot('novo-preview-390');
  await ev("fechar()");
  await ev("trocaAba('calendario')"); await sleep(200);
  out.largura_cal_390 = await ev("document.documentElement.scrollWidth");
  out.cal_titulo = await ev("document.getElementById('cal-titulo').innerText");
  out.cal_cont = await ev("document.getElementById('cal-cont').innerText");
  await shot('novo-cal-390');
  await ev("trocaAba('resultado')"); await sleep(200);
  out.largura_res_390 = await ev("document.documentElement.scrollWidth");
  await shot('novo-res-390');
  await cdp('Emulation.setDeviceMetricsOverride', {width: 1280, height: 900, deviceScaleFactor: 1, mobile: false});
  await ev("trocaAba('hoje')"); await sleep(500);
  await shot('novo-hoje-1280');
  console.log(JSON.stringify(out, null, 1));
  ws.close(); chrome.kill();
  process.exit(0);
})().catch(e => { console.error('ERRO', e); process.exit(1); });

